   FUNCTION pluginaccess (c_pluginid INTEGER, c_userid INTEGER DEFAULT UID)
      RETURN BOOLEAN
   IS
      CURSOR c_username
      IS
         SELECT username
           FROM all_users
          WHERE user_id = c_userid;

      g_res    cm_adm_usergrants%ROWTYPE;
      usname   c_username%ROWTYPE;
      uname    VARCHAR2 (255);
   BEGIN
      OPEN c_username;
      FETCH c_username INTO usname;

      IF c_username%NOTFOUND
      THEN
         RETURN FALSE;
      ELSE
         uname := usname.username;
      END IF;

      CLOSE c_username;

      SELECT *
        INTO g_res
        FROM cm_adm_usergrants
       WHERE pluginid = c_pluginid AND userid = c_userid;

      RETURN TRUE;
   EXCEPTION
      WHEN NO_DATA_FOUND
      THEN
         RETURN is_admin (uname);
   END;
   
   
   FUNCTION checkcredituser
      RETURN BOOLEAN
   IS
      RESULT   BOOLEAN;

      CURSOR c_crdusr
      IS
         SELECT NAME
           FROM cm_adm_users
          WHERE NAME = USER;

      crdusr   c_crdusr%ROWTYPE;
   BEGIN
      OPEN c_crdusr;
      FETCH c_crdusr INTO crdusr;
      RESULT := c_crdusr%FOUND;
      RETURN RESULT;
   END;

   PROCEDURE checkaccessoperation (DebitAccid IN INTEGER,
                                   CreditAccID in integer,
                                   VidOP in integer)
   IS
      RESULT   BOOLEAN;
      balacc   INTEGER;

      CURSOR c_denacc (p_bal IN INTEGER)
      IS
         SELECT bal_cn
           FROM cm_adm_operationgrants
          WHERE userid = (SELECT ID
                            FROM sb_user$
                           WHERE NAME = USER) AND bal_cn = p_bal;

      denacc   c_denacc%ROWTYPE;
   BEGIN
   
   if nvl(VidOP,0) <> cm_decls.cmTransactionOpType then 
      IF checkcredituser
      THEN
         SELECT bal_cn1
           INTO balacc
           FROM sb_account
          WHERE ID = Debitaccid;

         OPEN c_denacc (balacc);
         FETCH c_denacc INTO denacc;
         RESULT := c_denacc%FOUND;
         CLOSE c_denacc;

         SELECT bal_cn1
           INTO balacc
           FROM sb_account
          WHERE ID = Creditaccid;

         OPEN c_denacc (balacc);
         FETCH c_denacc INTO denacc;
         RESULT := Result or (c_denacc%FOUND);
         CLOSE c_denacc;

         IF RESULT
         THEN
            raise_application_error (-20007, '?iyeeeeao aia?ia? ieiac!');
         END IF;
      END IF;
      end if;
   END;
   

