              , NVL (scheduleinfo.interest, 0)
              , NVL (payments.payedamt, 0)
              , NVL (payments.payedintamt, 0)
              , NVL (payments_year.payedamt, 0)
              , NVL (payments_year.payedintamt, 0)
              , NVL (payments_mon.payedamt, 0)
