            AND c.creditid = p.ID
            AND h.creditid(+) = p.ID
            AND bp.creditid(+) = p.ID
            AND p.ID = p_id;

      CURSOR c_payments
      IS
         SELECT MAX (paydate) maxdate,
                NVL (SUM (payedamt + payeddueamt), 0) payedamt,
                NVL (SUM (payedintamt + payeddueintamt), 0) payedintamt
           FROM cm_all_payments
          WHERE creditid = p_id AND paydate <= p_edate;

      CURSOR c_paysched
      IS
         SELECT MAX (paymentdate) maxdat, NVL (SUM (principal), 0) principal,
                NVL (SUM (interest), 0) interest
           FROM cm_all_payment_schedule
          WHERE creditid = p_id AND paymentdate <= p_edate;

      CURSOR c_histinfo
      IS
         SELECT hdate, rest, interestrest interest, duerest, dueinterestrest,
                reserveid
           FROM agro_history
          WHERE creditid = p_id AND hdate = (SELECT MAX (hdate)
                                               FROM cm_history
                                              WHERE hdate <= p_edate);

      CURSOR c_accp (pdaty DATE)
      IS
         SELECT pok_ostat
           FROM cm_accounts a, smart.archost t
          WHERE a.secondaryreserveaccid = t.acc_id
            AND t.datdate = pdaty
            AND a.creditid = p_id;

      CURSOR c_accs (pdaty DATE)
      IS
         SELECT pok_ostat
           FROM cm_accounts a, smart.archost t
          WHERE a.primaryreserveaccid = t.acc_id
            AND t.datdate = pdaty
            AND a.creditid = p_id;

      crd   c_crdinfo%ROWTYPE;
      pay   c_payments%ROWTYPE;
      psc   c_paysched%ROWTYPE;
      his   c_histinfo%ROWTYPE;
      acp   c_accp%ROWTYPE;
      acs   c_accs%ROWTYPE;
      dm1   NUMBER;
      dm2   NUMBER;
      dm3   NUMBER;
      dm4   NUMBER;
      dm5   NUMBER;
      dd1   NUMBER;
      dd2   NUMBER;
      dd3   NUMBER;
      dd4   NUMBER;
      dd5   NUMBER;
      ac1   NUMBER;
      ac2   NUMBER;
      ac3   NUMBER;
      ac4   NUMBER;
      ac5   NUMBER;
   BEGIN
      OPEN c_crdinfo;
      FETCH c_crdinfo INTO crd;
      CLOSE c_crdinfo;
      OPEN c_payments;
      FETCH c_payments INTO pay;
      CLOSE c_payments;
      OPEN c_paysched;
      FETCH c_paysched INTO psc;
      CLOSE c_paysched;
      OPEN c_histinfo;
      FETCH c_histinfo INTO his;
      CLOSE c_histinfo;
      OPEN c_accp (his.hdate);
      FETCH c_accp INTO acs;
      CLOSE c_accp;
      OPEN c_accs (his.hdate);
      FETCH c_accs INTO acp;
      CLOSE c_accs;

      --if (psc.principal-pay.payedamt>0) then
      IF (ABS (psc.maxdat - p_edate) < 30)
      THEN
         dm1 := his.duerest;
         dd1 := his.interest;
      END IF;

      IF (ABS (psc.maxdat - p_edate) BETWEEN 30 AND 89)
      THEN
         dm2 := his.duerest;
         dd2 := his.interest;
      END IF;

      IF (ABS (psc.maxdat - p_edate) BETWEEN 90 AND 179)
      THEN
         dm3 := his.duerest;
         dd3 := his.interest;
      END IF;

      IF (ABS (psc.maxdat - p_edate) BETWEEN 180 AND 359)
      THEN
         dm4 := his.duerest;
         dd4 := his.interest;
      END IF;

      IF (ABS (psc.maxdat - p_edate) > 360)
      THEN
         dm5 := his.duerest;
         dd5 := his.interest;
      END IF;

      -- end if;

      IF his.reserveid = 2
      THEN
         ac1 := acp.pok_ostat;
      END IF;

      IF his.reserveid = 3
      THEN
         ac2 := acp.pok_ostat;
      END IF;

      IF his.reserveid = 4
      THEN
         ac3 := acs.pok_ostat;
      END IF;

      IF his.reserveid = 5
      THEN
         ac4 := acs.pok_ostat;
      END IF;

      IF his.reserveid = 6
      THEN
         ac5 := acs.pok_ostat;
      END IF;

      INSERT INTO cm_report_proviz
           VALUES (p_id, crd.boorowerid, crd.crdnum, crd.boorower,
                   crd.branchid, crd.branch, 0, '', crd.villageid, '',
                   crd.purposeid, '', crd.typeid, '', his.rest + his.duerest,
                   his.duerest, NVL (dm1, 0), NVL (dm2, 0), NVL (dm3, 0),
                   NVL (dm4, 0), NVL (dm5, 0), NVL (dd1, 0), NVL (dd2, 0),
                   NVL (dd3, 0), NVL (dd4, 0), NVL (dd5, 0), NVL (ac1, 0),
                   NVL (ac2, 0), NVL (ac3, 0), NVL (ac4, 0), NVL (ac5, 0),
                   NVL (0, 0), NVL (0, 0), NVL (0, 0), NVL (0, 0), NVL (0, 0));
   END;

   PROCEDURE insinfograntyear (p_id NUMBER, p_bdate DATE, p_edate DATE)
   IS
      CURSOR c_ginf
      IS
         SELECT m.machinename, grantyear, 1 machcnt, machineammount
           FROM cm_ak_grants g, cm_ak_machines m
          WHERE g.machineid = m.ID AND creditid = p_id;

      CURSOR c_payinfo
      IS
         SELECT SUM (payedamt + payeddueamt) payedamt,
                SUM (payedintamt + payeddueintamt) payedintamt
           FROM agro_payments
          WHERE creditid = p_id AND paydate <= p_edate;

      CURSOR c_payinfo_year
      IS
         SELECT SUM (payedamt + payeddueamt) payedamt,
                SUM (payedintamt + payeddueintamt) payedintamt
           FROM agro_payments
          WHERE creditid = p_id
            AND paydate BETWEEN TRUNC (p_edate, 'Y') AND p_edate;

      CURSOR c_payinfo_mon
      IS
         SELECT SUM (payedamt + payeddueamt) payedamt,
                SUM (payedintamt + payeddueintamt) payedintamt
           FROM agro_payments
          WHERE creditid = p_id AND paydate BETWEEN p_bdate AND p_edate;

      CURSOR c_pplane_year
      IS
         SELECT SUM (principal) princ
           FROM cm_all_payment_schedule
          WHERE creditid = p_id
            AND paymentdate BETWEEN TRUNC (p_edate, 'Y') AND p_edate;

      CURSOR c_pplane_mon
      IS
         SELECT SUM (principal) princ
           FROM cm_all_payment_schedule
          WHERE creditid = p_id AND paymentdate BETWEEN p_bdate AND p_edate;

      CURSOR c_histinfo
      IS
         SELECT rest
           FROM agro_history
          WHERE creditid = p_id AND hdate = (SELECT MAX (hdate)
                                               FROM cm_history
                                              WHERE hdate <= p_edate);

      ginf   c_ginf%ROWTYPE;
      paya   c_payinfo%ROWTYPE;
      payy   c_payinfo%ROWTYPE;
      paym   c_payinfo%ROWTYPE;
      plny   c_pplane_year%ROWTYPE;
      plnm   c_pplane_mon%ROWTYPE;
      hist   c_histinfo%ROWTYPE;
   BEGIN
      OPEN c_ginf;
      FETCH c_ginf INTO ginf;
      CLOSE c_ginf;
      /*
      open c_histinfo;
      fetch c_histinfo into hist;
      close c_histinfo;
    */
      OPEN c_payinfo;
      FETCH c_payinfo INTO paya;
      CLOSE c_payinfo;
      OPEN c_payinfo_year;
      FETCH c_payinfo_year INTO payy;
      CLOSE c_payinfo_year;
      OPEN c_payinfo_mon;
      FETCH c_payinfo_mon INTO paym;
      CLOSE c_payinfo_mon;
      OPEN c_pplane_mon;
      FETCH c_pplane_mon INTO plnm;
      CLOSE c_pplane_mon;
      OPEN c_pplane_year;
      FETCH c_pplane_year INTO plny;
      CLOSE c_pplane_year;

      INSERT INTO cm_report_grants
                  (creditid, tecyear, tecname, teccount,
                   tecamt, tecarend, payallmain, payallint,
                   overdebtyesr, payyearmain, payyearint, overdebtmon,
                   paymonmain, paymonint,
                   rest
                  )
           VALUES (p_id, ginf.grantyear, ginf.machinename, 1,
                   ginf.machineammount, 1, paya.payedamt, paya.payedintamt,
                   plny.princ, payy.payedamt, payy.payedintamt, plnm.princ,
                   paym.payedamt, paym.payedintamt,
                    ginf.machineammount - NVL (paya.payedamt, 0)
                  );
   END;

