   PROCEDURE maketemp (pbdat DATE, pedat DATE)
   IS
   BEGIN
      INSERT INTO agro_history
         SELECT creditid, hdate, lastcalcdate, stopcalcdate, rest,
                interestrest, duerest, dueinterestrest, reserveid,
                givenamount, obligation, pledgeprice, partitionkey,
                duereserveid, pledgepricetorpaq, pledgepriceev
           FROM cm_history
          WHERE hdate = (SELECT MAX (hdate)
                           FROM cm_history
                          WHERE hdate <= pedat);

      INSERT INTO agro_tranches
         SELECT ID, creditid, tranchedate, trancheamount
           FROM cm_all_tranches
          WHERE tranchedate <= pedat;

      INSERT INTO agro_payments
         SELECT ID, creditid, paydate, payedamt, payedintamt, payeddueamt,
                payeddueintamt, payedpenaltyamt
           FROM cm_all_payments
          WHERE paydate <= pedat;
   END;

   FUNCTION get_monthpayment (p_creditid IN INTEGER, p_date IN DATE)
      RETURN NUMBER
   IS
      RESULT      NUMBER;

      CURSOR c_pay (bdat IN DATE, edat IN DATE)
      IS
         SELECT SUM (payedamt) AS payamt
           FROM cm_payments
          WHERE creditid = p_creditid AND paydate BETWEEN bdat AND edat;

      lastdate    DATE;
      firstdate   DATE;
   BEGIN
      SELECT LAST_DAY (p_date)
        INTO lastdate
        FROM DUAL;

      SELECT (ADD_MONTHS (lastdate, -1) + 1)
        INTO firstdate
        FROM DUAL;

      OPEN c_pay (firstdate, lastdate);
      FETCH c_pay INTO RESULT;
      CLOSE c_pay;
      RETURN NVL (RESULT, 0);
   END;

   FUNCTION get_payint (pay_sh IN INTEGER, pdate IN DATE)
      RETURN NUMBER
   IS
      CURSOR pi
      IS
         SELECT payedintamt
           FROM cm_payments
          WHERE creditid = pay_sh AND paydate = pdate;

      RESULT   NUMBER;
   BEGIN
      OPEN pi;
      FETCH pi INTO RESULT;
      CLOSE pi;

      IF RESULT IS NULL
      THEN
         RESULT := 0;
      END IF;

      RETURN RESULT;
   END;

   FUNCTION get_planpayment (
      p_crdid    IN   INTEGER,
      p_optype   IN   INTEGER,
      p_dat      IN   DATE
   )
      RETURN NUMBER
   IS
      RESULT     NUMBER               := 0;

      CURSOR c_planrest
      IS
         SELECT principal, interest, ipinterest
           FROM cm_payment_schedule
          WHERE creditid = p_crdid AND paymentdate = p_dat;

      planrest   c_planrest%ROWTYPE;
   BEGIN
      OPEN c_planrest;
      FETCH c_planrest INTO planrest;
      CLOSE c_planrest;

      IF p_optype = cm_decls.cmpaymentmaintransactionoptype
      THEN
         RESULT := NVL (planrest.principal, 0);
      ELSE
         IF p_optype = cm_decls.cmpaymentinttransactionoptype
         THEN
            RESULT := NVL (planrest.interest, 0);
         END IF;
      END IF;

      RETURN RESULT;
   END;

