   FUNCTION get_creditfullpayamt (p_creditid IN INTEGER, p_dat IN DATE)
      RETURN NUMBER
   IS
      RESULT     NUMBER;

      CURSOR c_acc
      IS
         SELECT booroweraccid
           FROM cm_accounts
          WHERE creditid = p_creditid;

      boorrest   NUMBER;

      CURSOR c_payplan
      IS
         SELECT rest
           FROM cm_payment_schedule
          WHERE creditid = p_creditid
            AND paymentdate =
                        (SELECT MIN (paymentdate)
                           FROM cm_payment_schedule
                          WHERE creditid = p_creditid AND paymentdate > p_dat);

      planrest   NUMBER;
      acc        INTEGER;
   BEGIN
      OPEN c_payplan;
      FETCH c_payplan INTO planrest;
      CLOSE c_payplan;
      OPEN c_acc;
      FETCH c_acc INTO acc;
      CLOSE c_acc;

      IF acc IS NULL
      THEN
         RESULT := 0;
      END IF;

      boorrest := cm_common.accountrest_get (acc);
      RESULT := ROUND (0.99 * NVL (planrest, 0) - boorrest);
      RETURN RESULT;
   END;

