      CURSOR c_tranchesum
      IS
         SELECT SUM (trancheamount) amt
           FROM cm_tranches
          WHERE creditid = p_id;

      trsum   c_tranchesum%ROWTYPE;
      res     NUMBER;
   BEGIN
      /*Res :=   Mcreditdebtmaindebt (P_id)
             + Payedmaindebt (P_id);*/
      OPEN c_tranchesum;
      FETCH c_tranchesum INTO trsum;

      IF c_tranchesum%FOUND
      THEN
         res := trsum.amt;
      ELSE
         res := 0;
      END IF;

      CLOSE c_tranchesum;
      RETURN ROUND (res / 1000);
   END;

