   FUNCTION tamodenmishsay (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF (mcreditdebtmaindebt (p_id) = 0) AND (mcreditdebtintdebt (p_id) = 0)
      THEN
         RETURN 1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION tamodenmishesasmebleg (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF (tamodenmishsay (p_id) <> 0)
      THEN
         RETURN payedmaindebt (p_id);
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION tamodenmishfaizmebleg (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF (tamodenmishsay (p_id) <> 0)
      THEN
         RETURN payedintdebt (p_id);
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION qismenodenmishsay (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF     (payedmaindebt (p_id) > 0)
         AND (payedmaindebt (p_id) < creditsamount (p_id))
      THEN
         RETURN 1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION qismenodenmishesas (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF qismenodenmishsay (p_id) > 0
      THEN
         RETURN payedmaindebt (p_id);
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION qismenodenmishfaiz (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF qismenodenmishsay (p_id) > 0
      THEN
         RETURN payedintdebt (p_id);
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION tamodenilmemishsay (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      RETURN kreditqaligsay (p_id) - qismenodenmishsay (p_id);
   END;

   FUNCTION tamodenilmemishesas (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF tamodenilmemishsay (p_id) <> 0
      THEN
         RETURN creditsamount (p_id);
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION tamodenilmemishfaiz (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF tamodenilmemishsay (p_id) <> 0
      THEN
         RETURN payedintdebt (p_id);
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION kreditqaligsay (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF mcreditdebtmaindebt (p_id) <> 0
      THEN
         RETURN 1;
      ELSE
         RETURN 0;
      END IF;
   END;

   FUNCTION kreditqaligesas (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF kreditqaligsay (p_id) = 0
      THEN
         RETURN 0;
      ELSE
         RETURN mcreditdebtmaindebt (p_id);
      END IF;
   END;

   FUNCTION kreditqaligfaiz (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      IF kreditqaligsay (p_id) = 0
      THEN
         RETURN 0;
      ELSE
         RETURN mcreditdebtintdebt (p_id);
      END IF;
   END;

   FUNCTION cemiverilmishesas (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      RETURN ROUND (creditsamount (p_id) / 1000, 1);
   END;

   FUNCTION cemiverilmishfaiz (p_id INTEGER)
      RETURN NUMBER
   IS
   BEGIN
      RETURN ROUND (computedpercent (p_id) / 1000, 1);
   END;

   FUNCTION creditproject (p_id INTEGER)
      RETURN INTEGER
   IS
      CURSOR c_projid
      IS
         SELECT c.sid# proj_id
           FROM creditsmgr.cm_portfolio b,
                creditsmgr.cm_accounts a,
                sb_account c
          WHERE (a.creditid = b.ID)
            AND (c.ID = a.loanaccid)
            AND (b.ID = p_id);

      projid      c_projid%ROWTYPE;
      projectid   INTEGER;
   BEGIN
      OPEN c_projid;
      FETCH c_projid INTO projid;

      IF c_projid%FOUND
      THEN
         projectid := projid.proj_id;
      ELSE
         projectid := 0;
      END IF;

      CLOSE c_projid;
      RETURN projectid;
   END;
   
   function Get_SummTr(p_id in integer,bdat in date,edat in date)
   return number
   is
   result number;
    
    cursor c_summ(id in integer,p_bdat in date,p_edat in date)is
    select sum(TRANCHEAMOUNT) as amt from cm_tranches 
    where creditid  = id and TRANCHEDATE between p_bdat and p_edat;
     summ c_summ%rowtype;
   begin
    
    open c_summ(p_id,bdat,edat);
    fetch c_summ into summ;
    close c_summ;
    result := summ.amt;
    return result;
   end;
   
   function Get_SummPay(p_id in integer,bdat in date,edat in date)
   return number
   is
   result number;
    
    cursor c_summ(id in integer,p_bdat in date,p_edat in date)is
    select sum(PAYEDAMT) as amt from cm_payments 
    where creditid  = id and PAYDATE between p_bdat and p_edat;
     summ c_summ%rowtype;
   begin
    
    open c_summ(p_id,bdat,edat);
    fetch c_summ into summ;
    close c_summ;
    result := summ.amt;
    return result;
   end;
   
   function Get_rest(p_id in integer,p_dat in date)
   return number
   is
   cursor c_rests (id in integer,dat in date)is
   select rest from cm_history
   where creditid = id and hdate  = dat;
   
   rests c_rests%rowtype;
   begin
     open c_rests(p_id,p_dat);
     fetch c_rests into rests;
     close c_rests;
     return rests.rest;
   end;
   
END;
/


