CREATE OR REPLACE 
PACKAGE BODY            cm_akf_1
IS
   FUNCTION credit_count (cust_id IN INTEGER)
      RETURN NUMBER
   IS
      cnt   NUMBER;
   BEGIN
      SELECT COUNT (*)
        INTO cnt
