   FUNCTION overdatemaindebt (p_id IN INTEGER)
      RETURN NUMBER
   IS
      CURSOR c_interestsum
      IS
         SELECT SUM (  payedamt
                     + payeddueamt) AS intamt
           FROM cm_payments
          WHERE creditid = p_id;

      CURSOR c_archostat
      IS
         SELECT SUM (ABS (pok_ostat)) ostatok
           FROM sb_tenostat
          WHERE acc_id =
                    (SELECT loanaccid
                       FROM cm_accounts
                      WHERE creditid = p_id)
             OR acc_id = (SELECT dueloanaccid
                            FROM cm_accounts
                           WHERE creditid = p_id);

      intsum      c_interestsum%ROWTYPE;
      archostat   c_archostat%ROWTYPE;
      debt        NUMBER;
      odemdebt    NUMBER;
      ostdebt     NUMBER;
   BEGIN
      odemdebt := 0;
      ostdebt := 0;
      OPEN c_interestsum;
      FETCH c_interestsum INTO intsum;

      IF intsum.intamt IS NOT NULL
      THEN
         odemdebt := intsum.intamt;
      END IF;

      CLOSE c_interestsum;
      OPEN c_archostat;
      FETCH c_archostat INTO archostat;

      IF archostat.ostatok IS NOT NULL
      THEN
         ostdebt := archostat.ostatok;
      END IF;

      CLOSE c_archostat;
      debt :=   odemdebt
              + ostdebt;
      RETURN ROUND (debt / 1000);
   END;

   FUNCTION overdatemaindebt1 (p_id IN INTEGER, p_date IN DATE)
      RETURN NUMBER
   IS
      debt   NUMBER;
   BEGIN
      SELECT SUM (principal)
        INTO debt
        FROM cm_payment_schedule
       WHERE creditid = p_id AND paymentdate <= p_date;

      RETURN ROUND (debt / 1000);
   END;

   FUNCTION overdateintdebt1 (p_id IN INTEGER, p_date IN DATE)
      RETURN NUMBER
   IS
      debt   NUMBER;
   BEGIN
      /*SELECT SUM (interest)
        INTO Debt
        FROM Cm_payment_schedule
       WHERE Creditid = P_id AND Paymentdate <= P_date;*/
      debt := computedpercent (p_id) * 1000;
      RETURN ROUND (debt / 1000);
   END;

   FUNCTION overdatepercentdebt (p_id IN INTEGER)
      RETURN NUMBER
   IS
      CURSOR c_interestsum
      IS
         SELECT SUM (  payedintamt
                     + payeddueintamt) AS intamt
           FROM cm_payments
          WHERE creditid = p_id;

      CURSOR c_archostat
      IS
         SELECT SUM (ABS (pok_ostat)) ostatok
           FROM sb_tenostat
          WHERE acc_id = (SELECT interestaccid
                            FROM cm_accounts
                           WHERE creditid = p_id)
             OR acc_id = (SELECT dueinterestaccid
                            FROM cm_accounts
                           WHERE creditid = p_id);

      intsum      c_interestsum%ROWTYPE;
      archostat   c_archostat%ROWTYPE;
      debt        NUMBER;
      odemdebt    NUMBER;
      ostdebt     NUMBER;
   BEGIN
      odemdebt := 0;
      ostdebt := 0;
      OPEN c_interestsum;
      FETCH c_interestsum INTO intsum;

      IF intsum.intamt IS NOT NULL
      THEN
         odemdebt := intsum.intamt;
      END IF;

      CLOSE c_interestsum;
      OPEN c_archostat;
      FETCH c_archostat INTO archostat;

      IF archostat.ostatok IS NOT NULL
      THEN
         ostdebt := archostat.ostatok;
      END IF;

      CLOSE c_archostat;
      debt :=   odemdebt
              + ostdebt;
      RETURN ROUND (debt / 1000);
   END;

   FUNCTION payedalldebt (p_id IN INTEGER)
      RETURN NUMBER
   IS
      CURSOR c_maind
      IS
         SELECT SUM (  payedamt
                     + payeddueamt
                     + payedintamt
                     + payeddueintamt) AS pamt
           FROM cm_payments
          WHERE creditid = p_id;

      maind   c_maind%ROWTYPE;
      debt    NUMBER;
   BEGIN
      OPEN c_maind;
      FETCH c_maind INTO maind;
      debt := maind.pamt;

      IF c_maind%NOTFOUND
      THEN
         debt := 0;
      END IF;

      CLOSE c_maind;
      RETURN ROUND (debt / 1000);
   END;

