   FUNCTION mcreditdebtmaindebt (p_id IN INTEGER)
      RETURN NUMBER
   IS
      CURSOR c_accidl
      IS
         SELECT loanaccid acid
           FROM cm_accounts
          WHERE creditid = p_id;

      CURSOR c_accidd
      IS
         SELECT dueloanaccid acid
           FROM cm_accounts
          WHERE creditid = p_id;

      CURSOR c_ostat (accid IN INTEGER)
      IS
         SELECT ABS (pok_ostat) ostat
           FROM sb_tenostat
          WHERE acc_id = accid;

      accidl   c_accidl%ROWTYPE;
      accidd   c_accidd%ROWTYPE;
      ostatl   c_ostat%ROWTYPE;
      ostatd   c_ostat%ROWTYPE;
      debtl    NUMBER;
      debtd    NUMBER;
      res      NUMBER;
   BEGIN
      debtl := 0;
      debtd := 0;
      OPEN c_accidl;
      FETCH c_accidl INTO accidl;
      CLOSE c_accidl;
      OPEN c_accidd;
      FETCH c_accidd INTO accidd;
      CLOSE c_accidd;
      OPEN c_ostat (accidl.acid);
      FETCH c_ostat INTO ostatl;

      IF ostatl.ostat IS NOT NULL
      THEN
         debtl := ostatl.ostat;
      END IF;

      CLOSE c_ostat;
      OPEN c_ostat (accidd.acid);
      FETCH c_ostat INTO ostatd;

      IF ostatd.ostat IS NOT NULL
      THEN
         debtd := ostatd.ostat;
      END IF;

      CLOSE c_ostat;
      res :=   debtl
             + debtd;
      --creditsamount(p_id)-PayedMainDebt(p_id);
      res := 1000 * (  creditsamount (p_id)
                     - payedmaindebt (p_id)
                    );
      RETURN ROUND (res / 1000);
   END;

   FUNCTION mcreditdebtintdebt (p_id IN INTEGER)
      RETURN NUMBER
   IS
      CURSOR c_accidl
      IS
         SELECT interestaccid acid
           FROM cm_accounts
          WHERE creditid = p_id;

      CURSOR c_accidd
      IS
         SELECT dueinterestaccid acid
           FROM cm_accounts
          WHERE creditid = p_id;

      CURSOR c_ostat (accid IN INTEGER)
      IS
         SELECT ABS (pok_ostat) ostat
           FROM sb_tenostat
          WHERE acc_id = accid;

      accidl   c_accidl%ROWTYPE;
      accidd   c_accidd%ROWTYPE;
      ostatl   c_ostat%ROWTYPE;
      ostatd   c_ostat%ROWTYPE;
      debtl    NUMBER;
      debtd    NUMBER;
      res      NUMBER;
   BEGIN
      debtl := 0;
      debtd := 0;
      OPEN c_accidl;
      FETCH c_accidl INTO accidl;
      CLOSE c_accidl;
      OPEN c_accidd;
      FETCH c_accidd INTO accidd;
      CLOSE c_accidd;
      OPEN c_ostat (accidl.acid);
      FETCH c_ostat INTO ostatl;

      IF ostatl.ostat IS NOT NULL
      THEN
         debtl := ostatl.ostat;
      END IF;

      CLOSE c_ostat;
      OPEN c_ostat (accidd.acid);
      FETCH c_ostat INTO ostatd;

      IF ostatd.ostat IS NOT NULL
      THEN
         debtd := ostatd.ostat;
      END IF;

      CLOSE c_ostat;
      res :=   debtl
             + debtd;
      --creditsamount(p_id)-PayedMainDebt(p_id);
      --Res := CreditsAmount(p_id)-payedmaindebt(p_id);
      RETURN ROUND (res / 1000);
   /*
   Res :=   Computedpercent (P_id)
          - Payedintdebt (P_id);*/
   END;

   FUNCTION mcreditdebtovermaindebt (p_id IN INTEGER, p_date IN DATE)
      RETURN NUMBER
   IS
      res   NUMBER;
   BEGIN
      res :=   overdatemaindebt (p_id)
             - payedmaindebt (p_id);
