   FUNCTION f3payafterpretall (p_id INTEGER)
      RETURN NUMBER
   IS
      res       NUMBER;
      pretdat   DATE;
   BEGIN
      res := 0;
      pretdat := f3maindebtpretenziadate (p_id);

      IF pretdat IS NOT NULL
      THEN
         SELECT SUM (  payedamt
                     + payedintamt
                     + payeddueamt
                     + payeddueintamt) AS payamt
           INTO res
           FROM cm_payments
          WHERE creditid = p_id AND paydate >= pretdat;
      END IF;

      RETURN ROUND (res / 1000);
   END;

