               calcedint := 0;
            END IF;

            IF      get_periodintfortr (
                       p_creditid,
                       preddat,
                       get_tranchdatebyid (cardintrest_curr_state.tranchid)
                    ) = 0
                AND get_periodintfortr (
                       p_creditid,
                       tekdat,
                       get_tranchdatebyid (cardintrest_curr_state.tranchid)
                    ) <> 0
            THEN
               IF get_trrestfortrid (
                     cardintrest_curr_state.tranchid,
                     sbop.get_date
                  ) = 0
               THEN
                  calcedint := 0;
               ELSE
                  SELECT intrest
                    INTO calcedint
                    FROM cm_cardrest_curr_state
                   WHERE tranchid = cardintrest_curr_state.tranchid;
               END IF;
            END IF;

            result :=   result
                      + calcedint;
         END IF;
      END LOOP;

      COMMIT;
      RETURN result;
   END;

   PROCEDURE cancelcalculation (p_creditid IN INTEGER)
   IS
      CURSOR c_intrest_curr_state
      IS
         SELECT tranchid, interest
           FROM cm_cardintrest_curr_state
          WHERE tranchid IN
                   ((SELECT id
                       FROM cm_tranches
                      WHERE creditid = p_creditid));
   BEGIN
      FOR intrest_curr_state IN c_intrest_curr_state
      LOOP
         UPDATE cm_cardrest_curr_state
            SET intrest =   intrest
                          - intrest_curr_state.interest,
                trprocessed = 0
          WHERE tranchid = intrest_curr_state.tranchid;

         UPDATE cm_cardintrest_curr_state
            SET interest = 0
          WHERE tranchid = intrest_curr_state.tranchid;
      END LOOP;
   END;

   FUNCTION get_tranchdatebyid (p_id IN INTEGER)
      RETURN DATE
   IS
      result   DATE;
   BEGIN
      SELECT tranchedate
        INTO result
        FROM cm_tranches
       WHERE id = p_id;

      RETURN result;
   END;

   FUNCTION get_lessthanzeroint (p_creditid IN INTEGER)
      RETURN NUMBER
   IS
      result   NUMBER;

      CURSOR c_cardsetting
      IS
         SELECT MIN (annualintrate)
           FROM cm_calc_cardsettings
          WHERE cardid = (SELECT cardid
                            FROM cm_calc_cardcustsettings
                           WHERE categoryid = (SELECT customertype
                                                 FROM cm_portfolio
                                                WHERE id = p_creditid))
            AND annualintrate > 0;
   BEGIN
      OPEN c_cardsetting;
      FETCH c_cardsetting INTO result;
      CLOSE c_cardsetting;
      RETURN result;
   END;

   FUNCTION get_periodintfortr (
      p_creditid   IN   INTEGER,
      p_date       IN   DATE,
      p_trdat      IN   DATE
   )
      RETURN NUMBER
   IS
      result                NUMBER                      := 0;

      CURSOR c_cardsetting (p_period IN INTEGER)
      IS
         SELECT annualintrate
           FROM cm_calc_cardsettings
          WHERE cardid = (SELECT cardid
                            FROM cm_calc_cardcustsettings
                           WHERE categoryid = (SELECT customertype
                                                 FROM cm_portfolio
                                                WHERE id = p_creditid))
            AND p_period BETWEEN beginperiod AND endperiod;

      CURSOR c_fixedcardsetting (p_period IN INTEGER)
      IS
         SELECT annualintrate
           FROM cm_calc_cardsettings
          WHERE cardid = (SELECT cardid
                            FROM cm_calc_cardcustsettings
                           WHERE categoryid = (SELECT customertype
                                                 FROM cm_portfolio
                                                WHERE id = p_creditid))
            AND id > (SELECT MIN (id)
                        FROM cm_calc_cardsettings
                       WHERE NVL (fixedday, 0) = 0)
            AND p_period BETWEEN beginperiod AND endperiod;

      CURSOR c_fixednextperiod
      IS
         SELECT annualintrate, endperiod
           FROM cm_calc_cardsettings
          WHERE cardid = getcardid (p_creditid)
            AND id = (SELECT MIN (id)
                        FROM cm_calc_cardsettings
                       WHERE NVL (fixedday, 0) <= 0);

      lasttrdate            DATE;
      lasttramt             NUMBER;
      period                INTEGER;
      endfixedfirstperiod   NUMBER;
      endfixedsecperiod     NUMBER;
      fixednextperiod       c_fixednextperiod%ROWTYPE;
   BEGIN
      period := cm_utils.bankdaysbetween (p_trdat, p_date);
      
      endfixedfirstperiod :=   get_fixedday (p_creditid, p_trdat)
                             - p_trdat;
      OPEN c_cardsetting (period);
      FETCH c_cardsetting INTO result;
      CLOSE c_cardsetting;

      /* dbms_output.put_line(' get_fixedday (p_creditid,p_trdat) = '||get_fixedday (p_creditid,p_trdat));
       dbms_output.put_line(' p_trdat = '||p_trdat);
       dbms_output.put_line('endfixedfirstperiod =  '||endfixedfirstperiod);*/

      IF isfixeddaycard (getcardid (p_creditid))
      THEN --Main
         dbms_output.put_line(' endfixedfirstperiod =  '||endfixedfirstperiod);
         IF endfixedfirstperiod > 0
         THEN --1
            OPEN c_fixednextperiod;
            FETCH c_fixednextperiod INTO fixednextperiod;
            CLOSE c_fixednextperiod;
            endfixedsecperiod := fixednextperiod.endperiod;

            IF period BETWEEN endfixedfirstperiod AND endfixedsecperiod
            THEN
               result := fixednextperiod.annualintrate;
            END IF;
         ELSE
            OPEN c_fixedcardsetting (period);
            FETCH c_fixedcardsetting INTO result;
            CLOSE c_fixedcardsetting;
         END IF; --1   
      END IF; --Main

      /*IF NVL (RESULT, 0) = 0
      THEN
         RESULT := get_lessthanzeroint (p_creditid);
      END IF;*/
      RETURN result;
   END;

   FUNCTION getcardid (p_creditid IN INTEGER)
      RETURN INTEGER
   IS
      CURSOR c_cardcredits
      IS
         SELECT cardid
           FROM cm_calc_cardcustsettings
          WHERE categoryid = (SELECT customertype
                                FROM cm_portfolio
                               WHERE id = p_creditid);

      cardcredits   c_cardcredits%ROWTYPE;
      result        INTEGER;
   BEGIN
      OPEN c_cardcredits;
      FETCH c_cardcredits INTO cardcredits;
      result := cardcredits.cardid;
      CLOSE c_cardcredits;
      RETURN result;
   END;

   FUNCTION get_fixedday (p_creditid IN INTEGER, p_trdat IN DATE)
      RETURN DATE
   IS
      result   DATE;

      CURSOR c_cardsetting
      IS
         SELECT fixedday
           FROM cm_calc_cardsettings
          WHERE cardid = (SELECT cardid
                            FROM cm_calc_cardcustsettings
                           WHERE categoryid = (SELECT customertype
                                                 FROM cm_portfolio
                                                WHERE id = p_creditid))
            AND fixedday IS NOT NULL;

      trdat    DATE;
      YEAR     VARCHAR2 (5);
      mon      VARCHAR2 (5);
      DAY      VARCHAR2 (5);
      fday     INTEGER;
   BEGIN
      OPEN c_cardsetting;
      FETCH c_cardsetting INTO fday;
      CLOSE c_cardsetting;
      DAY := TO_CHAR (fday);
      trdat := ADD_MONTHS ( /*get_firsttranchedate (p_creditid)*/p_trdat, 1);
      YEAR := TO_CHAR (trdat, 'YYYY');
      mon := TO_CHAR (trdat, 'MON');
      result := TO_DATE (   DAY
                         || '-'
                         || mon
                         || '-'
                         || YEAR);
      RETURN result;
   END;

   FUNCTION isfixeddaycard (p_cardid IN INTEGER)
      RETURN BOOLEAN
   IS
      CURSOR c_cardsetting
      IS
         SELECT fixedday
           FROM cm_calc_cardsettings
          WHERE cardid = p_cardid AND fixedday IS NOT NULL;

      result        BOOLEAN;
      cardsetting   c_cardsetting%ROWTYPE;
   BEGIN
      OPEN c_cardsetting;
      FETCH c_cardsetting INTO cardsetting;
      result := c_cardsetting%FOUND;
      CLOSE c_cardsetting;
      RETURN result;
   END;

   FUNCTION get_firsttranchedate (p_creditid IN INTEGER)
      RETURN DATE
   IS
      result   DATE;

      CURSOR c_tr
      IS
         SELECT MIN (tranchedate) AS trdate
           FROM cm_tranches
          WHERE creditid = p_creditid;
   BEGIN
      OPEN c_tr;
      FETCH c_tr INTO result;
      CLOSE c_tr;
      RETURN result;
   END;

   FUNCTION get_cartcalcmethod (p_creditid IN INTEGER)
      RETURN VARCHAR2
   IS
      result   VARCHAR2 (50);

      CURSOR c_c
      IS
         SELECT NAME
           FROM cm_calc_cardmethods
          WHERE id = (SELECT calcmethod
                        FROM cm_calc_cardsorts
                       WHERE id = getcardid (p_creditid));
   BEGIN
      OPEN c_c;
      FETCH c_c INTO result;
      CLOSE c_c;
      RETURN result;
   END;

   FUNCTION checkcardcredits (p_creditid IN INTEGER)
      RETURN BOOLEAN
   IS
      CURSOR c_cardcredits
      IS
         SELECT categoryid
           FROM cm_calc_cardcustsettings
          WHERE categoryid = (SELECT customertype
                                FROM cm_portfolio
                               WHERE id = p_creditid);

      cardcredits   c_cardcredits%ROWTYPE;
      result        BOOLEAN;
   BEGIN
      OPEN c_cardcredits;
      FETCH c_cardcredits INTO cardcredits;
      result := c_cardcredits%FOUND;
      CLOSE c_cardcredits;
      RETURN result;
   END;

   FUNCTION check_calcedtr (p_trid IN INTEGER)
      RETURN INTEGER
   IS
      result   INTEGER;

      CURSOR c_cint
      IS
         SELECT trprocessed
           FROM cm_cardrest_curr_state
          WHERE tranchid = p_trid;

      cint     c_cint%ROWTYPE;
   BEGIN
      OPEN c_cint;
      FETCH c_cint INTO cint;
      result := cint.trprocessed;
      CLOSE c_cint;
      RETURN result;
   END;

   FUNCTION get_trrestfortrid (p_trid IN INTEGER, p_dat IN DATE)
      RETURN NUMBER
   IS
      result   NUMBER;

      CURSOR c_rest
      IS
         SELECT rest
           FROM cm_cardtrchrests
          WHERE tranchid = p_trid AND hdate = p_dat;
   BEGIN
      OPEN c_rest;
      FETCH c_rest INTO result;
      CLOSE c_rest;
      RETURN result;
   END;
END;
/


