   PROCEDURE tranche_creditcards (p_creditid IN INTEGER, trdate IN DATE)
   IS
      CURSOR c_port (p_id IN INTEGER)
      IS
         SELECT numberofcredit, currency, credittype, customertype, branchid,
                initialamount
           FROM cm_active_credits
          WHERE id = p_id;

      CURSOR c_account (p_id IN INTEGER)
      IS
         SELECT booroweraccid, loanaccid, primaryreserveaccid, interestaccid
           FROM cm_accounts
          WHERE creditid = p_id;

      CURSOR c_rate (p_id IN INTEGER)
      IS
         SELECT ostat
           FROM sb_temprate
          WHERE val_kod = p_id;

      CURSOR c_history (crdid IN INTEGER)
      IS
         SELECT lastcalcdate, rest, reserveid, givenamount, obligation
           FROM cm_curr_state
          WHERE creditid = crdid;

      CURSOR c_reserverate (p_id IN INTEGER)
      IS
         SELECT PERCENT
           FROM cm_reserves
          WHERE id = p_id;

      CURSOR c_credittype (p_id IN INTEGER)
      IS
         SELECT description
           FROM cm_credittypes
          WHERE id = p_id;

      port                c_port%ROWTYPE;
      accounts            c_account%ROWTYPE;
      rates               c_rate%ROWTYPE;
      history             c_history%ROWTYPE;
      reserverate         c_reserverate%ROWTYPE;
      crdtype             c_credittype%ROWTYPE;
      tramt               NUMBER;
      debitaccid          INTEGER;
      creditaccid         INTEGER;
      firsttranche        BOOLEAN;
      trdescription       VARCHAR2 (256);
      temp                NUMBER;
      resulttranchetrid   INTEGER;
      resultreservetrid   INTEGER;
      trancheid           INTEGER;
      tempinttrid         INTEGER;
      intaccid            INTEGER;
      invaccid            INTEGER;
      inttramt            NUMBER (18, 2);
   BEGIN
   
      OPEN c_port (p_creditid);
      FETCH c_port INTO port;
      CLOSE c_port;
      OPEN c_account (p_creditid);
      FETCH c_account INTO accounts;
      CLOSE c_account;
      OPEN c_history (p_creditid);
      FETCH c_history INTO history;
      CLOSE c_history;
      OPEN c_rate (port.currency);
      FETCH c_rate INTO rates;
      CLOSE c_rate;
      OPEN c_reserverate (history.reserveid);
      FETCH c_reserverate INTO reserverate;
      CLOSE c_reserverate;
      OPEN c_credittype (port.credittype);
      FETCH c_credittype INTO crdtype;
      CLOSE c_credittype;
      tramt := ABS (cm_common.accountrest_get (accounts.booroweraccid));
      firsttranche := port.initialamount = 0;

      IF firsttranche
      THEN
         UPDATE cm_active_credits
            SET initialamount = tramt,
                dateofgrant = trdate
          WHERE id = p_creditid;

         UPDATE cm_curr_state
            SET rest =   rest
                       + tramt,
                obligation =   obligation
                             - tramt,
                givenamount =   givenamount
                              + tramt
          WHERE creditid = p_creditid;
      ELSE
         UPDATE cm_curr_state
            SET rest =   rest
                       + tramt,
                obligation =   obligation
                             - tramt,
                givenamount =   givenamount
                              + tramt
          WHERE creditid = p_creditid;
      END IF;

      debitaccid := accounts.loanaccid;
      creditaccid := accounts.booroweraccid;
      trdescription := cm_utils.trdesctranche ();
      trdescription :=
           REPLACE (trdescription, cm_decls.trdescnumber, port.numberofcredit); -- TODO
      trdescription := REPLACE (
                          trdescription,
                          cm_decls.trdescdate,
                          TO_CHAR (trdate, 'DD/MM/YYYY')
                       );

      IF  tramt > 0 AND (debitaccid IS NOT NULL) AND (creditaccid IS NOT NULL)
      THEN
         resulttranchetrid :=
               cm_transactionmgr.cm_transactionadd (
                  p_trid=> NULL,
                  p_debitaccid=> debitaccid,
                  p_creditaccid=> creditaccid,
                  p_debitamount=> tramt,
                  p_creditamount=> NULL,
                  p_natamount=> NULL,
                  p_flags=> cm_decls.cmtrflaginbalance,
                  p_optype=> cm_decls.cmtransactionoptype,
                  p_inbalancechar=> NULL,
                  p_trdate=> trdate,
                  p_trdescription=> trdescription
               );
      END IF;

      intaccid := accounts.interestaccid;
      invaccid :=
            cm_utils.lnkinterestaccount (
               p_custcategory=> port.customertype,
               p_crdcurrency=> port.currency,
               p_bankid=> port.branchid
            );
      trdescription := cm_utils.trdescinterestrecalc;
      trdescription :=
           REPLACE (trdescription, cm_decls.trdescnumber, port.numberofcredit); -- TODO
      trdescription := 'E??aeo ?yooeiayi e?oeoaay eiie??eea?u - '||port.numberofcredit;
                       
      inttramt := ROUND (tramt / 100, 2);
      /*IF      (inttramt > 0)
          AND (intaccid IS NOT NULL)
          AND (invaccid IS NOT NULL)
      THEN
         tempinttrid :=
               cm_transactionmgr.cm_transactionadd (
                  p_trid=> NULL,
                  p_debitaccid=> intaccid,
                  p_creditaccid=> invaccid,
                  p_debitamount=> inttramt,
                  p_creditamount=> NULL,
                  p_natamount=> NULL,
                  p_flags=> cm_decls.cmtrflaginbalance,
                  p_optype=> cm_decls.cmtransactionoptype,
                  p_inbalancechar=> NULL,
                  p_trdate=> trdate,
                  p_trdescription=> trdescription
               );
            inttramt := ROUND (tramt / 100, 2);   
      END IF;*/

      IF cm_utils.creditreservecontenabled (p_credittypeid => port.credittype) =
                                                                             1
      THEN
         IF reserverate.PERCENT > 0
         THEN
            temp := cm_utils.calcpercent (
                       p_sum => tramt,
                       p_rate=> reserverate.PERCENT,
                       p_coefficient=> 1,
                       p_delimmer=> 1
                    );
            debitaccid :=
                  cm_utils.lnkreserveaccount (
                     p_custcategory=> port.customertype,
                     p_crdcurrency=> port.currency,
                     p_bankid=> port.branchid
                  );
            creditaccid := accounts.primaryreserveaccid;
            tramt := ROUND (rates.ostat * temp, 2);
            trdescription := cm_utils.trdescreserveincrease ();
            trdescription := REPLACE (
                                trdescription,
                                cm_decls.trdescnumber,
                                port.numberofcredit
                             ); -- TODO
            trdescription := REPLACE (
                                trdescription,
                                cm_decls.trdescdate,
                                TO_CHAR (trdate, 'DD/MM/YYYY')
                             );

            IF      tramt > 0
                AND (debitaccid IS NOT NULL)
                AND (creditaccid IS NOT NULL)
            THEN
               resultreservetrid :=
                     cm_transactionmgr.cm_transactionadd (
                        p_trid=> NULL,
                        p_debitaccid=> debitaccid,
                        p_creditaccid=> creditaccid,
                        p_debitamount=> tramt,
                        p_creditamount=> NULL,
                        p_natamount=> NULL,
                        p_flags=> cm_decls.cmtrflaginbalance,
                        p_optype=> cm_decls.cmtransactionoptype,
                        p_inbalancechar=> NULL,
                        p_trdate=> trdate,
                        p_trdescription=> trdescription
                     );
            END IF;
         END IF;

         INSERT INTO cm_tranches
                     (creditid, tranchedate,
                      trancheamount,
                      tranchetrid, reservetrid/*,profittrid*/)
              VALUES (p_creditid, trdate,
                      ABS (cm_common.accountrest_get (accounts.booroweraccid)),
                      resulttranchetrid, resultreservetrid/*,tempinttrid*/)
           RETURNING id
                INTO trancheid;

         add_cardtrchrests (
            p_cardid=> cm_calcsettings.getcardid (p_creditid),
            p_tranchid=> trancheid,
            p_rest=> ABS (cm_common.accountrest_get (accounts.booroweraccid))
         );
         
         /*update cm_curr_state
         set interestrest =interestrest+nvl(inttramt,2)
         where creditid  = p_creditid;*/
         
      END IF;
      
INSERT INTO cm_tranches
                     (creditid, tranchedate,
                      trancheamount,
                      tranchetrid, reservetrid/*,profittrid*/)
              VALUES (p_creditid, trdate,
                      ABS (cm_common.accountrest_get (accounts.booroweraccid)),
                      resulttranchetrid, resultreservetrid/*,tempinttrid*/)
           RETURNING id
                INTO trancheid;

         add_cardtrchrests (
            p_cardid=> cm_calcsettings.getcardid (p_creditid),
            p_tranchid=> trancheid,
            p_rest=> ABS (cm_common.accountrest_get (accounts.booroweraccid))
         );

   END;

   FUNCTION control_creditcards (p_brid IN INTEGER)
      RETURN VARCHAR2
   IS
      result   VARCHAR2 (2048);
   BEGIN
      result :=
               'select p.numberofcredit,
       cm_common.accountnumber_get(a.contractaccid) as contractno,
       cm_common.accountrest_get(a.booroweraccid) as CustRest,
       h.rest 
       from cm_active_credits p,
       cm_accounts a,
       cm_curr_state h
      where p.id = a.creditid
        and   p.id=h.creditid 
       and   cm_common.accountrest_get(a.booroweraccid)<0
       and CM_CARDS.IsCreditCards(p.id) = 1
        and p.BranchID = '
            || p_brid;
      RETURN result;
   END;

   FUNCTION iscreditcards (p_creditid IN INTEGER)
      RETURN NUMBER
   IS
      result   INTEGER := 0;
   BEGIN
      IF cm_calcsettings.checkcardcredits (p_creditid)
      THEN
         result := 1;
      END IF;

      RETURN result;
   END;

   PROCEDURE committranche (docommit IN BOOLEAN DEFAULT TRUE)
   IS
   BEGIN
      IF docommit
      THEN
         cm_transactionmgr.cm_commitdelayedtransactions;
         COMMIT WORK;
      ELSE
         ROLLBACK WORK;
      END IF;
   END;

   PROCEDURE add_cardtrchrests (
      p_cardid     IN   INTEGER,
      p_tranchid   IN   INTEGER,
      p_rest       IN   NUMBER
   )
   IS
   preddat date;
   BEGIN
   
   select pred_dat into preddat from sb_sysdat;
   
      INSERT INTO cm_cardtrchrests
                  (hdate, cardid, tranchid, rest, intrest, partkey)
           VALUES (sbop.get_date, p_cardid, p_tranchid, p_rest, 0, 0);

      INSERT INTO cm_cardtrchintrests
                  (hdate, cardid, tranchid, interest, partkey)
           VALUES (sbop.get_date, p_cardid, p_tranchid, 0, 0);


      INSERT INTO cm_cardtrchrests
                  (hdate, cardid, tranchid, rest, intrest, partkey)
           VALUES (preddat, p_cardid, p_tranchid, 0, 0, 1);

      INSERT INTO cm_cardtrchintrests
                  (hdate, cardid, tranchid, interest, partkey)
           VALUES (preddat, p_cardid, p_tranchid, 0, 1);

   END;

   PROCEDURE del_cardtranches (p_tranchid IN INTEGER)
   IS
   BEGIN
      DELETE      cm_cardtrchrests
            WHERE tranchid = p_tranchid AND hdate = sbop.get_date;

      COMMIT;
   END;

   PROCEDURE del_cardpayments (p_paymentid IN INTEGER)
   IS
      CURSOR c_pay
      IS
         SELECT id, paymentdate, paymentid, tranchid, maindebit, intdebit
           FROM cm_cardpayments
          WHERE paymentid = p_paymentid AND paymentdate = sbop.get_date;
   BEGIN
      FOR cardpayments IN c_pay
      LOOP
         UPDATE cm_cardrest_curr_state
            SET rest =   rest
                       - cardpayments.maindebit,
                intrest =   intrest
                          - cardpayments.intdebit
          WHERE tranchid = cardpayments.tranchid;
      END LOOP;

      DELETE      cm_cardpayments
            WHERE paymentid = p_paymentid;
   END;

   PROCEDURE cardpayments_addedit (
      p_paymentdate   IN   DATE,
      p_paymentid     IN   INTEGER,
      p_tranchid      IN   INTEGER,
      p_maindebit     IN   NUMBER DEFAULT 0,
      p_intdebit      IN   NUMBER DEFAULT 0
   )
   IS
   BEGIN
      INSERT INTO cm_cardpayments
                  (paymentdate, paymentid, tranchid, maindebit,
                   intdebit)
           VALUES (p_paymentdate, p_paymentid, p_tranchid, p_maindebit,
                   p_intdebit);
   END;

   PROCEDURE add_cardpayments (
      p_creditid       IN   INTEGER,
      p_maindebt       IN   NUMBER DEFAULT 0,
      p_maininterest   IN   NUMBER DEFAULT 0,
      p_paymentid      IN   INTEGER
   )
   IS
      CURSOR c_cardtrchrests
      IS
         SELECT   tranchid, rest, intrest
             FROM cm_cardtrchrests
            WHERE tranchid IN
                     (SELECT id
                        FROM cm_tranches
                       WHERE creditid = p_creditid)
              AND hdate = sbop.get_date
         ORDER BY tranchid;

      cardtrchrests   c_cardtrchrests%ROWTYPE;
      tekdat          DATE;
      preddat         DATE;
      temppay         NUMBER;
      temp            NUMBER;
      tranchamt       NUMBER;
      fixedtrid       INTEGER;
   BEGIN
      SELECT tek_dat, pred_dat
        INTO tekdat, preddat
        FROM sb_sysdat;

      
/*------------------------PayMainDebit-----------------*/
      temppay := p_maindebt;

      FOR cardtrchrests IN c_cardtrchrests
      LOOP
         tranchamt := cardtrchrests.rest;
         temp :=   tranchamt
                 - temppay;

         IF temp > 0
         THEN
            temppay := 0;
            fixedtrid := cardtrchrests.tranchid;

            UPDATE cm_cardtrchrests
               SET rest = temp
             WHERE tranchid = cardtrchrests.tranchid AND hdate =
                                                                sbop.get_date;

            cardpayments_addedit (
               p_paymentdate=> sbop.get_date,
               p_paymentid=> p_paymentid,
               p_tranchid=> cardtrchrests.tranchid,
               p_maindebit=> temppay,
               p_intdebit=> 0
            );
            EXIT;
         ELSE
            temppay := ABS (temp);

            UPDATE cm_cardtrchrests
               SET rest = 0
             WHERE tranchid = cardtrchrests.tranchid AND hdate =
                                                                sbop.get_date;

            cardpayments_addedit (
               p_paymentdate=> sbop.get_date,
               p_paymentid=> p_paymentid,
               p_tranchid=> cardtrchrests.tranchid,
               p_maindebit=> cardtrchrests.rest,
               p_intdebit=> 0
            );
         END IF;
      END LOOP;

      
/*------------------------PayInterestDebit-----------------*/
      temppay := p_maininterest;

      FOR cardtrchrests IN c_cardtrchrests
      LOOP
         tranchamt := cardtrchrests.intrest;
         temp :=   tranchamt
                 - temppay;

         IF temp > 0
         THEN
            temppay := 0;
            fixedtrid := cardtrchrests.tranchid;

            UPDATE cm_cardtrchrests
               SET intrest = temp
             WHERE tranchid = cardtrchrests.tranchid AND hdate =
                                                                sbop.get_date;

            cardpayments_addedit (
               p_paymentdate=> sbop.get_date,
               p_paymentid=> p_paymentid,
               p_tranchid=> cardtrchrests.tranchid,
               p_maindebit=> temppay,
               p_intdebit=> 0
            );
            EXIT;
         ELSE
            temppay := ABS (temp);

            UPDATE cm_cardtrchrests
               SET intrest = 0
             WHERE tranchid = cardtrchrests.tranchid AND hdate =
                                                                sbop.get_date;

            cardpayments_addedit (
               p_paymentdate=> sbop.get_date,
               p_paymentid=> p_paymentid,
               p_tranchid=> cardtrchrests.tranchid,
               p_maindebit=> cardtrchrests.intrest,
               p_intdebit=> 0
            );
         END IF;
      END LOOP;
   -- COMMIT;
   END;
END;
/


