CREATE OR REPLACE 
PACKAGE BODY cm_common
IS

  function AccountNumber_Get(p_ID in Integer)
  return
  
      varchar2
      
  is
  
    cursor C_ACCOUNT(AccID in Integer) is
    select ACC_NO 
      from SB_Account 
     where ID=AccID;
  
  Result SB_ACCOUNT.ACC_NO%type;   
     
  begin
    
    open C_ACCOUNT(p_ID);
    fetch C_ACCOUNT into Result;
    close C_ACCOUNT;
    
    return Result;   
    
  end;     

 function get_accname(p_baxtiyarturan in integer)
 return varchar2
 is
 Result varchar2(225);
 cursor c_n is
     select name 
    from sb_account where id = p_baxtiyarturan;

 begin
    open c_n ;
    fetch c_n into result;
    close c_n;
    return Result;
 end;

  function AccountRest_Get(p_ID in Integer)
  return
  
      Number
       
  is
  
    cursor C_ACCREST(AccID in Integer) is
    select OSTAT
      from SB_TENOSTAT 
     where ACC_ID=AccID;
     
  Result Number := 0;  
     
  begin
    
    open C_ACCREST(p_ID);
    fetch C_ACCREST into Result;
    close C_ACCREST;
    
    return Result;   
    
  end;     
  
  
  procedure SecurityLog(
            p_CreditID in Integer ,
            p_Event in VarChar2
            )
  is
  begin
    
    insert into CM_SECURITYLOG(
    CreditID , Event
    ) 
    values(
    p_CreditID , p_Event
    );
    
  end;
    
 function Get_AccID(
              p_custid in integer,
              p_typeid in integer,
              p_defbalance in integer default 0/*=sb*/)
 return integer
 is
 
 cursor c_accid(cid in integer,ptid in integer)is
 SELECT   ac.id AS id
    FROM sb_account ac
   WHERE ac.kli_id = cid
   and
  (ac.bal_cn1 IN (SELECT accountnumber
                           FROM cm_aginfo
                          WHERE groupid = (SELECT g.id
                                             FROM cm_accountgroups g
                                            WHERE g.id = ptid)));
 
 cursor c_outaccid(cid in integer,ptid in integer)is
 SELECT  ac.id AS id
    FROM SBOUT_ACCOUNT ac
   WHERE ac.kli_id = cid
   and 
  (ac.bal_cn1 IN (SELECT accountnumber
                           FROM cm_aginfo
                          WHERE groupid = (SELECT g.id
                                             FROM cm_accountgroups g
                                            WHERE g.id = ptid)));
 Result integer;
  
 begin
   
   if p_defbalance = 0 then
      open c_accid(p_custid,p_typeid);
      fetch c_accid into Result;
      close c_accid;
   end if;

  if p_defbalance <> 0 then
      open c_outaccid(p_custid,p_typeid);
      fetch c_outaccid into Result;
      close c_outaccid;
   end if;
   
   return Result;
    
 end;
 
   function get_CreditMumber(p_id in integer)
  return varchar2
  is
   result varchar2(35);
   begin
      
      select numberofcredit 
         into result 
      from cm_portfolio
      where id=p_id;
      
      return result;
         
   end;
   
   function Get_LastMainPaydate(p_id in integer,p_dat in date)
   return date
   is
      cursor c_p is
      select max(PAYDATE) from cm_payments
      where PAYEDAMT<>0 and creditid=p_id
      and PAYDATE <= p_dat;
   result date;
   
      cursor c_tr is
      select max(tranchedate)
        from cm_tranches
       where creditid = p_id;
         
   begin
      open c_p ;
      fetch c_P into result;
      
      if result is null then
         open c_tr;
         fetch c_tr into result;
         close c_tr;
      end if;
      
      return result;
      
   end;
   
     function Get_LastintPaydate(p_id in integer,p_dat in date)
   return date
   is
      cursor c_p is
      select max(PAYDATE) from cm_payments
      where PAYEDINTAMT<>0 and creditid=p_id
      and PAYDATE <= p_dat;
   result date;

       cursor c_tr is
      select max(tranchedate)
        from cm_tranches
       where creditid = p_id;

 
   begin
      open c_p ;
      fetch c_P into result;
      close c_P;
      
      if result is null then
      open c_tr;
      fetch c_tr into result;
      close c_tr; 
      end if;
      
      return result;
      
   end;
  
  
  function Ge_InterestProqnoz(p_id in integer,
                                p_dat in date,
                                p_datproq in date,
                                p_proq in number)
  return number
  is
   result number;
   MainRest number;
   AnnInt number; 
   temp integer;
   d date;
  begin

    select Rest into MainRest
    from cm_history where creditid = p_id
    and hdate=p_dat;
  
    select annualyinterestrate into AnnInt
    from cm_portfolio where id = p_id;
    
   --temp := p_datproq-Get_LastintPaydate(p_id)+p_proq;
    d:= Get_LastintPaydate(p_id,p_dat); 
   
    if d is not null then 
   temp := cm_utils.bankdaysbetween(Get_LastintPaydate(p_id,p_dat),p_datproq);
   end if;
  --raise_application_error(-20007,' Q= '||temp);
   if  p_datproq-Get_LastintPaydate(p_id,p_dat)<=30 then
   temp :=30;
   end if;
   
   result := round(MainRest*AnnInt/36000*temp,2);
   return result;
     
  end;

  function Get_RestProqnoz(p_id in integer,
                              p_dat in date,
                              p_progDat in date ) 
  return number
  is
   result number;
   MainRest number;
   AnnInt number; 
   temp number;
   ProlondDate date;
   currdat date;
   duefirstcontract date;
   
   cursor c_pay is
   select principal from cm_payment_schedule
   where creditid = p_id and paymentdate
   between cm_utils.get_firstmonth(p_progDat) and cm_utils.get_lastmonth(p_progDat);
   
  begin
   
   
     
    select Rest into MainRest
    from cm_history where creditid = p_id
    and hdate=p_dat;

    select DUEDATEFIRSTCONTRACT into duefirstcontract
    from cm_portfolio
    where id = p_id;
     
    select cm_utils.bankdaysbetween(p_progDat,duefirstcontract)/30 into AnnInt
    from cm_portfolio where id = p_id;
   
    if AnnInt<=1 then AnnInt:=1; end if;
    
   result := round(MainRest/(round(AnnInt,1)));

   open c_pay;
   fetch c_pay into result;
   close c_pay;
      
   return result;
     
  end;
  
  function Get_CreditTranches(p_id in integer,
                              p_bdat in date,
                              p_edat in date)
  return number
  is
  result number;
  
  cursor c_Tr is
  select sum(TRANCHEAMOUNT)
  from cm_tranches 
  where creditid = p_id
  and TRANCHEDATE between p_bdat and p_edat;
  
  begin
     open c_Tr;
     fetch c_Tr into Result;
     close c_Tr;
     return nvl(Result,0);
  end;                            
                                 
