                              p_edat in date)
  return number
  is
  result number;
  
  cursor c_Pay is
  select sum(PAYEDAMT)
  from cm_payments
  where creditid = p_id
  and PAYDATE between p_bdat and p_edat;
  
  begin
     open c_Pay;
     fetch c_Pay into Result;
     close c_Pay;
     return nvl(Result,0);
  end;                            


  function Get_CreditIntPayments(p_id in integer,
