  is
  result number;
  
  cursor c_Pay is
  select sum(PAYEDINTAMT)
  from cm_payments
  where creditid = p_id
  and PAYDATE between p_bdat and p_edat;
  
  begin
     open c_Pay;
     fetch c_Pay into Result;
     close c_Pay;
     return nvl(Result,0);
  end;                            
  
  function Get_ProlongDate(p_id in integer)
  return date
  is
   result date;
   cursor c_exp is
   select max(newclosedate) from 
     cm_prolongations
   where creditid = p_id;
     
  begin
   open c_exp;
   fetch c_exp into result;
   close c_exp;
   return result;
  end;

  function Get_ExpDate(p_id in integer)
  return date
  is
   result date;
   cursor c_exp is
   select max(EXPDATE) from 
     cm_expires
   where creditid = p_id;
     
  begin
