   fetch c_exp into result;
   close c_exp;
   return result;
  end;


  function Get_LastAnnInt(p_id in integer)
  return number
  is
   result number;

   cursor c_portA is
   select annualyinterestrate from 
     cm_portfolioarchive
   where id = p_id
   and sysdat =(select min(sysdat) from cm_portfolioarchive);
     
  begin
   open c_portA;
   fetch c_portA into result;
   close c_portA;
   
   return p_id;
  end;

  function Get_CreditCalcStatus(p_id in integer)
  return varchar2
  is
   result varchar2(7);
   StCalcDat date;
   cursor c_curr is
   select stopcalcdate from 
     cm_curr_state
   where creditid = p_id;
     
  begin
   open c_curr;
   fetch c_curr into StCalcDat;
   close c_curr;
   
   if StCalcDat is null then
   result := 'Uy'; 
   else 
   result := 'Ei?';
   end if;
   return result;
  end;
 
  function Get_CountProlong(p_id in integer)
  return integer
  is
   result integer;
   cursor c_exp is
   select count(*) from 
     cm_prolongations
   where creditid = p_id;
     
  begin
   open c_exp;
   fetch c_exp into result;
   close c_exp;
   return result;
  end;
         
    function GetPeriod(bdat in date,edat in date)
   return integer
   is
   begin
      return MONTHS_BETWEEN(edat,bdat);
   end;
          
          
