CREATE OR REPLACE 
PACKAGE cm_control
IS
   TYPE cursor_type IS REF CURSOR;

   PROCEDURE open_cursor (cur OUT cursor_type, pstr IN VARCHAR2);
  PROCEDURE control(p_BrID in integer,p_dat in Date);
END;
