      p_insurancedate         IN   DATE,
      p_pledgepriceevkv       IN   NUMBER DEFAULT 0,
      p_pledgepricetorpaqha   IN   NUMBER DEFAULT 0
   )
   IS
   BEGIN
      boorowerinfo_add (p_creditid              => p_creditid,
