function GenerateOneAccno(p_bal_cn in integer,
                          p_Cust in integer,
                          p_val in integer,
                          p_Fil in integer,
                          p_Const in varchar2,
                          p_MCrdFil in integer)
return varchar2 is

   Result varchar2(25);

   cursor c_ball_cn(p_ball in integer,ConstVal in varchar2) is
   select id, bal_acc from cm_generatechildaccounts
   where genid = (select id from cm_generatemainaccounts 
   where bal_acc = p_ball and name = ConstVal); 

   
   cursor c_AccCount(p_Br in varchar2,p_bal in integer) is
   select max(id)  from sb_account
   where acc_no like p_bal||p_Br||'%';
   
   cursor c_acc (p_id in integer)is
   select acc_no from sb_account
   where id=p_id;
   
   cursor c_kod_Filial(p_Fid in integer)
   is select kod_filial from sb_filial
   where id = p_Fid;

   ball_cn c_ball_cn%rowtype;
   AccCount integer;
   LastaccNo varchar2(20); 
   fil c_kod_filial%rowtype;
   val varchar2(10);
begin


   val := to_char(p_val);
   
   if p_val =0 then
      val := '00';
   end if;
   
   if p_val =1 then
      val := '01';
   end if;
        
   open c_ball_cn(p_bal_cn,p_Const);
   fetch c_ball_cn into  ball_cn;
   close c_ball_cn;
   
   open c_kod_Filial(p_fil);
   fetch c_kod_Filial into fil;
   close c_kod_Filial;

   
   Result :=ball_cn.bal_acc||fil.kod_filial
   ||val;
   
   return result;

end; 
              

