CREATE OR REPLACE 
PACKAGE BODY            cm_deca
IS
  function NeqativeAsZero(p_Value in Number)
  return Number
  is
  begin
    if p_Value < 0 then
      return 0;
    else
      return p_Value;
    end if;
  end;

  function DueDaysCount(
      p_Date1 in date,
      p_Date2 in Date
  ) return Integer
  is
    Result Integer;
  begin
    Result := Trunc(p_Date1 - p_Date2);
    Result := NeqativeAsZero(Result);
    return Result;
  end;

  function OiaForLastThreeMonths(p_Date1 in Date,
              p_Date2 in Date,
              p_DueIntrst in Number)
  return Number
  is
    Result Number;
  begin
    if DueDaysCount(p_Date1,p_Date2) > 60 then
      Result := p_DueIntrst;
    else
      Result := 0;
    end if;
    return Result;
  end;

 function Get_CreditStatus(p_CrdID in integer,p_dat in date)
 return varchar2
 is
  Result varchar2(10);

  Cursor c_rest is
  select rest,
         interestrest,
         duerest,
         dueinterestrest
  from cm_history
  where hdate=p_dat and creditid=p_crdid;

  restinfo c_rest%rowtype;

 begin

    open c_rest;
    fetch c_rest into restinfo;
    close c_rest;

    if (restinfo.rest =0) and(restinfo.interestrest =0)
    and (restinfo.duerest =0)and(restinfo.dueinterestrest =0) then Result:='001';
    else Result:='006';
    end if;
   return result;
 end;

 function Get_CreditTypes(p_CrdID in integer)
 return varchar2
 is
  Result varchar2(10);

  Cursor c_type is
  SELECT renewablestatus, itype, iclass, cardtype
    FROM cm_credittypes
    WHERE ID = (SELECT credittype
               FROM cm_portfolio
              WHERE ID = p_crdid);

  typeinfo c_type%rowtype;

 begin

    open c_type;
    fetch c_type into typeinfo;
    close c_type;

    if (typeinfo.ITYPE = 1)  then Result:='002';
    

    elsif (typeinfo.cardtype = 1)  then Result:='003';

    else Result:='001';
    end if;
    
   return result;
 end;
 function Get_LastCreditPayment(p_CrdID in integer)
 return date
 is
  Result date;

 begin

   select max(PAYDATE) into Result from cm_payments where creditid = p_crdid;

   return result;
   
 exception
   when NO_DATA_FOUND
   then
   return null;

 end;
function Get_CreditPaymentAmount(p_CrdID in integer)
 return number
 is
  Result number(18);

 begin

   select principal+INTEREST into Result from cm_payment_schedule where
   id=(select min(id) from cm_payment_schedule where creditid = p_crdid);

   return result;

exception
   when NO_DATA_FOUND
   then
   return 0;

 end;
 function Get_ReserveAccountOstat(p_CrdID in integer)
 return number
 is
  Result number(18);

 begin
 
 
   select pok_ostat into Result from sb_tenostat where
   acc_id=(select PRIMARYRESERVEACCID from cm_accounts where creditid=p_crdid);
   
   return result;

exception
   when NO_DATA_FOUND
   then
   return 0;

 end;
 function Get_CustDateOfBirth(p_CrdID in integer)
 return DATE
 is
  Result date;

 begin

   select birthday into Result from sb_custinfo where
   id=(select min(id) from sb_custinfo where idcust=p_CrdID);

   return result;

exception
   when NO_DATA_FOUND
   then
   return null;

 end;
  function Get_CustPlaceOfBirth(p_CrdID in integer)
 return varchar2
 is
  Result varchar2(50);

 begin

   select birthplace into Result from sb_custinfo where
   id=(select min(id) from sb_custinfo where idcust=p_CrdID);

   return result;

exception
   when NO_DATA_FOUND
   then
   return null;

 end;
 function Get_CreditLineAmount(p_CrdID in integer)
 return number
 is
  Result number;

  Cursor c_type is
  SELECT renewablestatus, itype, iclass, cardtype
    FROM cm_credittypes
    WHERE ID = (SELECT credittype
               FROM cm_portfolio
              WHERE ID = p_crdid);

  typeinfo c_type%rowtype;
  
  Cursor c_amt is
  SELECT creditlineamount
  FROM cm_portfolio
    WHERE ID = p_crdid;

  amtinfo c_amt%rowtype;

 begin

    open c_type;
    fetch c_type into typeinfo;
    close c_type;
    
    open c_amt;
    fetch c_amt into amtinfo;
    close c_amt;


    if (typeinfo.ITYPE = 1)  then Result:=amtinfo.creditlineamount;


    elsif (typeinfo.cardtype = 1)  then Result:=amtinfo.creditlineamount;

    else Result:=0;
    end if;
    
   return result;
 end;
 
 function Get_CreditInitialAmount(p_CrdID in integer)
 return number
 is
  Result number;

  Cursor c_type is
  SELECT renewablestatus, itype, iclass, cardtype
    FROM cm_credittypes
    WHERE ID = (SELECT credittype
               FROM cm_portfolio
              WHERE ID = p_crdid);

  typeinfo c_type%rowtype;

  Cursor c_amt is
  SELECT INITIALAMOUNT
  FROM cm_portfolio
    WHERE ID = p_crdid;

  amtinfo c_amt%rowtype;

 begin

    open c_type;
    fetch c_type into typeinfo;
    close c_type;

    open c_amt;
    fetch c_amt into amtinfo;
    close c_amt;


     if (typeinfo.ITYPE = 1)  then Result:=0;


    elsif (typeinfo.cardtype = 1)  then Result:=0;

    else Result:=amtinfo.INITIALAMOUNT;
    end if;

   return result;
 end;

END;
