---------------------Other Functions-----------------------------
function crdGetTrchDate(c_id number)
  return date
  is
  res date; 
begin
  select nvl(max(tranchedate),sysdate)
    into res
    from cm_tranches
   where creditid=c_id;
   return res;  
end;

procedure tmaddnewticket (credid number, descc varchar2 default '')
is
   cursor c_crd
   is
      select creditlineamount amnt, usrgroup kbank, purposeofcredit dsc
        from cm_portfolio
       where id = credid;

   cursor c_acs
  is
    select a.name, a.acc_no, s.inn from cm_accounts c, sb_account a, sb_customers s where a.id=c.contractaccid and kli_id=s.id and c.creditid=credid;

   cursor c_cust
   is
      select a.booroweraccid from cm_accounts a where creditid=credid;
      
   cursor c_set (bid number)
   is
      select * from cm_banksettings where bankid=bid;
      
   crd    c_crd%rowtype;
   acs    c_acs%rowtype;
   set1   c_set%rowtype;
   cust   c_cust%rowtype;
begin
   open c_crd;
   fetch c_crd into crd;
   close c_crd;

   open c_acs;
   fetch c_acs into acs;
   close c_acs;

   open c_set (crd.kbank);
   fetch c_set into set1;
   close c_set;

   
   open c_cust;
   fetch c_cust into cust;
   close c_cust;

   insert into smart.tm_archive
               (pdate, dbankfilial, ammount, userid, status, kbankfilial,
                dacc_no, daccname, daccinn, kacc_no, kaccname, kaccinn,
                description, ticktype)
      select tek_dat, smart.sb_aca.getuserfilialid (user), crd.amnt, uid, 1,
             crd.kbank, acs.acc_no, acs.name, acs.inn, set1.acc_no,
             set1.name, set1.inn, descc, 1
        from sb_sysdat;

   cm_tranche.tranche_add(credid,getcurrdate,cust.booroweraccid,crd.amnt);
   cm_tranche.committranche;

   commit;
end;

function getbankname(bid number)
  return varchar2
is
  res varchar2(200);
begin
  select description
    into res
    from cm_usergroups
   where id=bid;
  return res;
  exception when no_data_found then
    return '-';
end;  

function getcurrdate
  return date
is
  res date;
begin
  select tek_dat
    into res
    from sb_sysdat;
  return res;
end;

---------------------Other Functions-----------------------------
END;
/


