          );*/
     
     end if;
     
    
   
     
    if cm_utils.Get_CrdCalcMethod(p_CreditID) = 'CalcMethodForPlanRest' then 
    
     if (cm_utils.Get_creditPenalty(p_CreditID) <> p_PenaltyRest) and
