        CM_UTILS.ProcessError(0);
     end if;
    
    if p_PenaltyRest > 0 then
       if p_PenaltyRest > CrdPenaltyRest then
          CM_UTILS.ProcessError(0);        
       end if;
       
       if p_PenaltyAccID is null then
          CM_UTILS.ProcessError(0);       
       end if;

       DebitAccID := p_CustAccID;
       CreditAccID := p_PenaltyAccID;
