         p_rate => CrdPReserveRate ,
         p_coefficient => 1 ,
         p_delimmer => 1
         )*rates.ostat - archostinfo.pok_ostat;
        
   --  raise_application_error(-20007,'ewfwe=='||(PortfInfo.CREDITLINEAMOUNT - (HistInfo.Rest -p_MainDebt)));
       DebitAccID := 
