       TrDescription := '?uoyeeeei ?eeiyoeyiae?eeiy?e ? '|| PortfInfo.numberofcredit/*CM_UTILS.trDescObligationReduce()*/;
       TrDescription := Replace(TrDescription,CM_DECLS.TrDescNumber,PortfInfo.NUMBEROFCREDIT); -- TODO
