CREATE OR REPLACE 
PACKAGE cm_preports
is
  procedure insrowpayment(p_id number, p_bdate date, p_edate date);
end;
/


CREATE OR REPLACE 
PACKAGE BODY                       cm_preports
is

procedure insrowpayment(p_id number, p_bdate date, p_edate date)
is
  cursor c_psched is
    select sum(principal) principal,sum(round(ipinterest,2)) interest
      from cm_payment_schedule
     where creditid=p_id and paymentdate between p_bdate and p_edate;
     
  cursor c_payment is
    select sum(payedamt)payedamt, sum(payedintamt)payedintamt,
           sum(payeddueamt)payeddueamt, sum(payeddueintamt)payeddueintamt
      from cm_payments
     where creditid=p_id and paydate between p_bdate and p_edate;

  cursor c_crdinf is
    select p.numberofcredit cnum, b.name boorower, u.description groupname
      from cm_boorowerinfo b, cm_portfolio p, cm_usergroups u
     where p.id=b.creditid and u.id=p.usrgroup and p_id=p.id;
     
  cursor c_hinf is
    select interestrest
      from cm_history
     where hdate=p_bdate and creditid=p_id;

  psched    c_psched%rowtype;
  payment   c_payment%rowtype;
  crdinf    c_crdinf%rowtype;
  hinf      c_hinf%rowtype;
begin
  open c_crdinf;
  fetch c_crdinf into crdinf;
  close c_crdinf;
  
  open c_payment;
  fetch c_payment into payment;
  close c_payment;

  open c_psched;
  fetch c_psched into psched;
  close c_psched;

  open c_hinf;
  fetch c_hinf into hinf;
  close c_hinf;

  insert into cm_report_payments
  values(
    p_id,
    crdinf.groupname,
    crdinf.boorower,
    crdinf.cnum,
    psched.principal,
    payment.payedamt+payment.payeddueamt,
    hinf.interestrest,
    payment.payedintamt+payment.payeddueintamt
  );
end;

end;
/


-- End of DDL Script for Package CHINAR.CM_PREPORTS

