CREATE OR REPLACE 
PACKAGE BODY                       cm_schedule_
IS

  
  
  function AnnutyPayment_Get(
             p_Amount in Number ,
             p_Rate in Number ,
             p_Periods in Integer ,
             p_PeriodRate in Integer
             )
  return Number           
  is
    
    Result Number(18,2);
    
  begin
  
    Result := p_Amount * 
              Power((1 + p_Rate/12/100),p_Periods)*
              p_Rate/12/100/(Power((1 + p_Rate/12/100), p_Periods)-1);
    
    return Result;
                  
  end;
  
  function EqualPartsPayment_Get(
             p_Amount in Number ,
             p_Rate in Number ,
             p_Periods in Integer ,
             p_PeriodRate in Integer
             )
  return Number           
  is
    Result Number(18,2);    
  begin
  
    Result := p_Amount / p_Periods;
    
    return Result;
                  
  end;
  
  procedure InsertAnnutySchedule(
             p_CreditID in Integer ,
             p_Amount in Number ,
             p_Rate in Number ,
             p_FirstPayDate in Date ,
             p_StartDate in Date , 
             p_Periods in Integer ,
             p_PeriodRate in Integer -- In Months 
            )
  is
    AnnutyPayment Number;
    IntrAmt Number;
    PrincipialAmt Number;
    FullPayment Number := p_Amount;
    PayDate Date := p_FirstPayDate;
    DayCnt Integer; 
    Temp integer;
    CrdRest Number (18,2);
    sumpay number;
    f boolean :=false;
    
  begin
  
    
    
    AnnutyPayment := AnnutyPayment_Get(FullPayment,p_Rate,p_Periods,p_PeriodRate);

    DayCnt := CM_UTILS.BankDaysBetween(p_StartDate,p_FirstPayDate);
    IntrAmt := CM_UTILS.CalcPercent(FullPayment,p_Rate,30/*DayCnt*/);
    PrincipialAmt := AnnutyPayment - IntrAmt;
    CrdRest := FullPayment - PrincipialAmt;
   

    Temp := PaymentSchedule_AddEdit(0,
                                    p_CreditID,
                                    Get_AnnutyDate(add_months(PayDate,-1),to_char(p_FirstPayDate,'DD'),p_CreditID,false),
                                    PrincipialAmt,
                                    IntrAmt,
                                    CrdRest);
    FullPayment := p_Amount - PrincipialAmt; 
    
    for i in 2..p_Periods 
    loop
     
      IntrAmt := CM_UTILS.CalcPercent(FullPayment,p_Rate,p_PeriodRate * 30);
      PrincipialAmt := AnnutyPayment - IntrAmt;
      PayDate := Get_AnnutyDate(PayDate,to_char(/*p_StartDate*/add_months(p_FirstPayDate,-1),'DD'),p_CreditID,f)/*ADD_MONTHS(PayDate,1)*/;
      CrdRest := FullPayment - PrincipialAmt;
      f := true;
      Temp := PaymentSchedule_AddEdit(0,p_CreditID,PayDate,PrincipialAmt,IntrAmt,CrdRest);
      if FullPayment >= PrincipialAmt then 
        FullPayment := FullPayment - PrincipialAmt;
      else
        FullPayment := 0;
      end if;
             
    end loop;
    
    
   /* select sum(PRINCIPAL) into sumpay from CM_PAYMENT_SCHEDULE
    where creditid = p_CreditID
    and paymentdate = (select max(paymentdate) from CM_PAYMENT_SCHEDULE
    where paymentdate<(select max(paymentdate) from CM_PAYMENT_SCHEDULE where creditid  = p_CreditID)
    and creditid =p_CreditID);*/
    
    update CM_PAYMENT_SCHEDULE
    set rest=0
    where creditid = p_CreditID
    and paymentdate = (select max(paymentdate) from CM_PAYMENT_SCHEDULE where creditid = p_CreditID);
         
  end;          

  procedure InsertEqualSchedule(
             p_CreditID in Integer ,
             p_Amount in Number ,
             p_Rate in Number ,
             p_FirstPayDate in Date ,
             p_StartDate in Date , 
             p_Periods in Integer ,
             p_PeriodRate in Integer -- In Months 
            )
  is
    EqualPayment Number;
    IntrAmt Number;
    PrincipialAmt Number;
    FullPayment Number := p_Amount;
    PayDate Date := p_FirstPayDate;
    DayCnt Integer; 
    Temp Integer;
    CrdRest number;
  begin
    
    EqualPayment := EqualPartsPayment_Get(FullPayment,p_Rate,p_Periods,p_PeriodRate);
    
    DayCnt := CM_UTILS.BankDaysBetween(p_StartDate,p_FirstPayDate);
    
    IntrAmt := CM_UTILS.CalcPercent(p_Amount,p_Rate,DayCnt);
    PrincipialAmt := EqualPayment;
    crdrest := FullPayment-PrincipialAmt;
    Temp := PaymentSchedule_AddEdit(0,p_CreditID,PayDate,PrincipialAmt,IntrAmt,crdrest);
    FullPayment := p_Amount - EqualPayment; 
    
    for i in 2..p_Periods 
    loop
      IntrAmt := CM_UTILS.CalcPercent(FullPayment,p_Rate,p_PeriodRate * 30);
      PrincipialAmt := EqualPayment;
      PayDate := ADD_MONTHS(PayDate,1);
      crdrest := FullPayment-PrincipialAmt;
      Temp := PaymentSchedule_AddEdit(0,p_CreditID,PayDate,PrincipialAmt,IntrAmt,crdrest);
      if FullPayment >= EqualPayment then 
        FullPayment := FullPayment - EqualPayment;
      else
        FullPayment := 0;
      end if;
             
    end loop;
         
  end;          
  
  function  PaymentSchedule_AddEdit(
              p_ID in Integer ,  
              p_CreditID in Integer ,
              p_PayDate in Date ,
              p_Principial in Number ,
              p_Interest in Number ,
              p_Rest in Number default null
             )
  return Integer              
  is
  
    Result Integer;
    
    cursor c_rest is
    select sum (REST) as smrest
    from CM_PAYMENT_SCHEDULE
    where creditid = p_CreditID;
    
    crdlineamt number;
    sumrest number;
    sumpay number;
    
  begin
    
    select CREDITLINEAMOUNT into crdlineamt
    from cm_portfolio where id = p_CreditID;
    
    update CM_PAYMENT_SCHEDULE
       set PAYMENTDATE = p_PayDate ,
           PRINCIPAL = p_Principial ,
           INTEREST = p_Interest ,
           Rest = p_Rest
     where ID = p_ID;
    
    if SQL%ROWCOUNT = 0 then
    
    insert into CM_PAYMENT_SCHEDULE(
      CREDITID , PAYMENTDATE , PRINCIPAL , INTEREST,REST
    )
    values (
    p_CreditID ,p_PayDate ,p_Principial ,p_Interest,p_Rest
    ) returning ID into Result; 
    
    end if;
    
    
    if p_Rest is null then
        
        open c_rest;
        fetch c_rest into sumrest;
        close c_rest;
        
        
        --if nvl(sumrest,0) = 0 then sumrest:=crdlineamt;
          -- else
             select sum(PRINCIPAL) into sumpay from CM_PAYMENT_SCHEDULE
             where creditid = p_CreditID;
             
             sumrest:=crdlineamt - sumpay;
          
       -- end if;
       -- raise_application_error(-20007,'sumrest = '||sumrest);
        update  CM_PAYMENT_SCHEDULE
            set rest=sumrest
            where id=Result;
    end if;
     
    --commit work;
           
    return Result;
    
  end;              
  
  procedure PaymentSchedule_Delete(p_ID in Integer)
  is
  begin
    delete from CM_PAYMENT_SCHEDULE where ID = p_ID;
    --commit work;
  end;
  
  
  procedure TrSchedule_Add(p_id integer, p_date date, p_ammount integer)
  is
  begin
    insert into cm_tranche_schedule (creditid, trchdate, trchamount)
         values (p_id, p_date, p_ammount);
  end;
  
  procedure TrSchedule_Edit(t_id integer, p_date date, p_ammount integer)
  is
  begin
    update cm_tranche_schedule
       set trchdate = p_date,
           trchamount = p_ammount
     where id = t_id;
  end;
  
  
  procedure TrSchedule_Del(t_id integer)
  is
  begin
    delete from cm_tranche_schedule
          where id = t_id;
  end;
  

  
 function DefDate(p_date in date,p_BeginDatechr in varchar2,p_creditid in integer,p_first in boolean)
 return date
is
  result date;
  Day varchar2(5);
  Mon varchar2(5);
  Year varchar2(5);

  RDay varchar2(5);
  RMon varchar2(5);
  RYear varchar2(5);
  ldat varchar2(5);
  
  cursor c_p(bdat in date,edat in date) is
  select *from cm_payment_schedule
  where creditid = p_creditid
  and paymentdate between bdat and edat;

    cursor c_cp(bdat in date,edat in date) is
  select count(*) as cnt from cm_payment_schedule
  where creditid = p_creditid
  and paymentdate between bdat and edat;
    
  fmdat date;
  lmdat date;
  
  cfmdat date;
  clmdat date;


  p c_p%rowtype;
  cp c_cp%rowtype;
  d boolean;
  d1 boolean;
  cont integer;
begin

   fmdat := cm_utils.get_firstmonth(add_months(p_date,-1));
   lmdat := cm_utils.get_lastmonth(add_months(p_date,-1));

   cfmdat := cm_utils.get_firstmonth(p_date);
   clmdat := cm_utils.get_lastmonth(p_date);
   

   Day := to_char(p_date,'DD');
   Mon := to_char(p_date , 'MON');
   Year := to_char(p_date,'YYYY'); 
     ldat:= to_char(last_day(p_date),'DD');
    
   result := ADD_MONTHS(p_date,1);

   RMon := to_char(Result , 'MON');
   RYear := to_char(Result,'YYYY'); 
   RDay := to_char(Result,'DD');
   
   if (p_BeginDatechr <> RDay) then
 
       if to_number(RDay) < to_number(p_BeginDatechr) then
           result := to_date(RDay||'-'||RMon||'-'||RYear);
       else     
           result := to_date(p_BeginDatechr||'-'||RMon||'-'||RYear);
       end if;
       
   end if; 
   
   open c_P(fmdat,lmdat);
   fetch c_p into p;
     d:= c_p%found;
   close c_p;
   
   open c_cP(cfmdat,clmdat);
   fetch c_cp into cont;

   close c_cp;
      
   if p_first then    
   if not d and not cont =2 then
    if (p_BeginDatechr <> Day) then
      if to_number(ldat) < to_number(p_BeginDatechr) then
          result := (to_date(ldat||'-'||Mon||'-'||Year));
         else
          result := to_date(p_BeginDatechr||'-'||Mon||'-'||Year); 
      end if;
   end if; 
   end if;  
   end if;
   

   return result;
END;
  
  function Get_AnnutyDate(p_date in date,p_char in varchar2,p_creditid in integer,first in boolean)
  return date
  is
    result date;
    
    cursor c_seldate(dat in date) is
     select seldate
     from cm_seldates
     where  seldate = dat ;
     
     sdate c_seldate%rowtype;
     checkdate  boolean := True;
      
   begin
     
      result := DefDate(p_date,p_char,p_CreditID,first);  
      if cm_utils.Check_EndWeek(result) then
        
         result := result + 1;
         
      end if;   

      
     
      while  checkdate 
      loop
         
         open c_seldate(result);
         fetch c_seldate into sdate;
         checkdate := c_seldate%found;
         close c_seldate;
        
         if not checkdate then 
         exit; 
         end if;
          
         result := result +1;  
      end loop;
                        
      return result;
         
   end; 
    
END;
/


