   END;

   PROCEDURE get_payments (
      bdat         IN   DATE,
      edat         IN   DATE,
      val_kod      IN   INTEGER,
      bper         IN   NUMBER,
      eper         IN   NUMBER,
      pername      IN   VARCHAR2,
      perid        IN   NUMBER,
