      apay      NUMBER;
      prid      NUMBER;
   BEGIN
      OPEN c_pay (bdat, edat, val_kod, bper, eper, pername, persontype);
      FETCH c_pay INTO payinfo;
      CLOSE c_pay;
      spay := NVL (payinfo.cspay, 0);
      apay := NVL (payinfo.capay, 0);

      IF spay <> 0
      THEN
         apay := apay / spay;
      END IF;

