           FROM sb_operkurs
          WHERE val_kod = v AND dat = p_d;

      oblinfo     c_obl%ROWTYPE;
      ostatinfo   c_ostat%ROWTYPE;
      sobl        NUMBER;
      aobl        NUMBER;
      prid        NUMBER;
   BEGIN
      OPEN c_ostat (val_kod, dat);
      FETCH c_ostat INTO ostatinfo;
      CLOSE c_ostat;
      OPEN c_obl (dat, val_kod, bper, eper, pername, persontype);
