  procedure MarkStateHistory(CurrentBankDate in Date);
  function chek_calcint return boolean;
END; -- Package spec
/


CREATE OR REPLACE 
PACKAGE BODY cm_system
IS

  procedure MarkStateHistory(CurrentBankDate in Date)
  is    
  begin
   --  Marking Rest History
   
update cm_history partition(prev_state)
set partitionkey = 2;

update cm_history partition(curr_state)
set partitionkey = 1;


   insert into CM_HISTORY
   (creditid, hdate, lastcalcdate, stopcalcdate, rest, interestrest,
    duerest, dueinterestrest, reserveid, givenamount, obligation,
    pledgeprice, partitionkey,duereserveid,pledgepricetorpaq,pledgepriceev,penaltyrest
   )
   select creditid, CurrentBankDate , lastcalcdate, stopcalcdate, rest, interestrest,
       duerest, dueinterestrest, reserveid, givenamount, obligation,
       pledgeprice, 0,duereserveid,pledgepricetorpaq,pledgepriceev,penaltyrest from CM_PREV_STATE;  
   
   -- Marking Interest History
   
    
update CM_INTERESTS partition(prev_state)
set partitionkey = 2;

update CM_INTERESTS partition(curr_state)
set partitionkey = 1;


    insert into CM_INTERESTS(partitionkey, creditid, hdate, interest, dueinterest, inttrid,
       dueinttrid, trprocessed, intprecision, dueintprecision,penaltyprecision, penaltyinterest
    ) 
    SELECT 0, creditid, CurrentBankDate, 0, 0, null,
       null, 0, intprecision, dueintprecision,penaltyprecision, 0
    FROM CM_INT_PREVSTATE;  
    
    
    -- Marking CreditCards History 
    
    /*  UPDATE cm_cardtrchintrests PARTITION (prev_state)
         SET partkey = 2;

      UPDATE cm_cardtrchintrests PARTITION (curr_state)
         SET partkey = 1;

      INSERT INTO cm_cardtrchintrests PARTITION (curr_state)
         SELECT CurrentBankDate, cardid, tranchid, 0, 0
           FROM cm_cardtrchintrests PARTITION (prev_state);
          

      UPDATE cm_cardtrchrests PARTITION (prev_state)
         SET partkey = 2;

      UPDATE cm_cardtrchrests PARTITION (curr_state)
         SET partkey = 1;

      INSERT INTO cm_cardtrchrests PARTITION (curr_state)
         SELECT CurrentBankDate, cardid, tranchid, rest, intrest, 0,0
           FROM cm_cardtrchrests PARTITION (prev_state);   */
           
  end;
  
  
  function chek_calcint return boolean
  is
  result boolean;
  
  cursor c_check is
  select count(*) from cm_curr_state
  where stopcalcdate is null
  and ((rest <> 0 )or (duerest = 0))
  and hdate <> lastcalcdate
  and creditid in (select id from cm_active_credits);
  
  
  cnt number;
  begin

   open c_check ;
   fetch  c_check into cnt;
   close c_check;

   result := (cnt=0);
   return result;
  end;
END;
/


-- End of DDL Script for Package CHINAR.CM_SYSTEM

