  begin
  
    /* if cm_utils.Get_CrdCalcMethod(p_CreditID) = 'CalcMethodForPlanRest' then
     if not  cm_utils.checkplane(p_CreditID) then
         
         raise_application_error(-20007,'?дямя планы йохду?!');
         
