              ) 
     return INTEGER 
     is  
     Result Integer; 
     Temp Integer; 
     begin 
      
       if p_TRID is NULL then 
        
       if p_Flags = CM_DECLS.cmTrFlagInBalance then 
        
         select SB_TR_SEG_PROVARCH.nextval 
     			into Temp 
     			from dual; 
           
       else
        
         select SBOUT_TR_SEG_PROVARCH.nextval 
     			into Temp 
     			from dual;
               
       end if; 
           
       else 
        
         Temp := p_TrID; 
          
