 function CheckPaymentDate(p_CrdID in integer,p_dat in date)
 return boolean is
   Amt number;
   
   cursor c_PayPlane is
   select principal
      from cm_payment_schedule
   where CreditID = p_CrdID
   and PaymentDate  = p_dat;
   

   cursor c_PayPlanedat(dat date) is
   select PaymentDate
      from cm_payment_schedule
   where CreditID = p_CrdID
   and  PaymentDate between get_firstmonth (dat) and dat;
    
   PayPlane c_PayPlane%rowtype;
   Result Boolean := false;
   planrest number;
   realrest number;
   
   pdat date;
   r boolean;
   currdat date;
 begin
   select tek_dat into currdat from sb_sysdat;
   

  planrest := Get_creditPlanOstat(p_CrdID);
  
  select rest into realrest from cm_curr_state
  where creditid = p_CrdID;
  
  Result := planrest <> realrest;
    
    open c_PayPlane;
    fetch c_PayPlane into PayPlane;
    r :=  c_PayPlane%found ;
    close c_PayPlane;
    
    open c_PayPlanedat(last_day(currdat));
    fetch c_PayPlanedat into pdat;
    close  c_PayPlanedat;
    
    
    if not result then 
      result := pdat >  currdat;
    end if;  
    
    Return Result;
    
 end;
 
