function get_firstmonth(p_date in date)
return date
is
  result date;
  Mon varchar2(4);
  year varchar2(4);
begin
   Mon := to_char(p_date,'MON');
   Year := to_char(p_date,'YYYY');
   return to_date('01'||'-'||Mon||'-'||year);  
end;

function get_lastmonth(p_date in date)
return date
is
  result date;
  Mon varchar2(4);
  year varchar2(4);
  fdat date;
begin
   Mon := to_char(p_date,'MON');
   Year := to_char(p_date,'YYYY');
   fdat :=to_date('01'||'-'||Mon||'-'||year);
   return last_day(fdat);  
end;

