  function Get_MainPlanPayment(p_creditid in integer)
  return number
  is
    result number := 0;
    
   cursor c_PayPlane is
   select sum
   (principal) as pay
      from cm_payment_schedule
   where CreditID = p_creditid
   and PaymentDate  <= (select tek_dat from sb_sysdat);

   cursor c_pay is
   select sum(PAYEDAMT) as pay
   from cm_payments
   where creditid = p_creditid;
   
   
   fdat date;
   ldat date;
   currdat date;
   
   factpay number;
   planpay number;
      
  begin
  
    select tek_dat into currdat from sb_sysdat;
    
     open c_PayPlane;
     fetch c_PayPlane into planpay;
     close c_PayPlane;
     
     open c_pay;
     fetch c_pay into factpay;
     close c_pay;
     
     if cm_utils.Get_CrdCalcMethod(p_CreditID) = 'CalcMethodForPlanRest' then
     result := nvl(planpay,0)-nvl(factpay,0);
     
     if result < 0 then
        result := 0;
     end if;
        
     
      if not Get_CrdCalcMethod(p_CreditID) = 'CalcMethodForPlanRest' then

     if  get_ExpiresDateCount(p_creditid) = 0 and
        get_crdcurrentpaymentdat(p_creditid) <> currdat

     then
       result := 0;
     end if;


        select rest into result from cm_curr_state
        where creditid = p_creditid;
     end if;    
     end if;   
     return result;
      
  end;
  

  
  function Get_IntPlanPayment(p_creditid in integer)
  return number
  is
    result number;
    
   cursor c_PayPlane is
   select sum
   (INTEREST) as pay
      from cm_payment_schedule
   where CreditID = p_creditid
   and PaymentDate  <= (select tek_dat from sb_sysdat);

   cursor c_pay is
   select sum(PAYEDINTAMT) as pay
   from cm_payments
   where creditid = p_creditid;
   
   
   fdat date;
   ldat date;
   currdat date;
   
   factpay number;
   planpay number;
      
  begin
     open c_PayPlane;
     fetch c_PayPlane into planpay;
     close c_PayPlane;
     
     open c_pay;
     fetch c_pay into factpay;
     close c_pay;
     
     result := nvl(planpay,0)-nvl(factpay,0);
     
     if result < 0 then
        result := 0;
     end if;     
     
     
     if not Get_CrdCalcMethod(p_CreditID) = 'CalcMethodForPlanRest' then

     if  get_ExpiresDateCount(p_creditid) = 0 and
        get_crdcurrentpaymentdat(p_creditid) <> currdat

     then
        result := 0;
     end if;


        select interestrest into result from cm_curr_state
        where creditid = p_creditid;
        
     end if;
     return result;
      
  end;
   
   
  function  get_ExpiresDateCount(p_creditid in integer)
  return number
  is
   result number := 0;
  

    currdat date;
    currRest number;
    LastExpDat date;
    tempdat date;
    
    cursor c_h(p_dat in date) is
     select min(hdate)   from cm_history
        where creditid = p_creditid
        and hdate >= p_dat;
    
  begin
     
     select tek_dat into currdat
     from sb_sysdat;
    
     select rest into currRest
     from cm_curr_state
     where creditid = p_creditid ;
     
     if cm_utils.Get_CrdCalcMethod(p_CreditID) = 'CalcMethodForPlanRest'  then
       
     if abs(Get_creditPlanRest(p_creditid,currdat)-currRest)<=15 then
        Result :=0;
       
     else
        
        select max(hdate) into tempdat  
        from cm_history
        where creditid = p_creditid
        and abs(Get_FacticalCalcRate1(p_creditid,hdate)-Rest) <=15;
        
      /*  if LastExpDat is null then
           raise_application_error(-20007,'Crdid = '||p_creditid);
        end if;*/
        
        --raise_application_error(-20007,'Crdid = '||tempdat);
        open c_h(tempdat);
        fetch c_h into LastExpDat;
        close c_h;
         
        if LastExpDat is null then
                  LastExpDat := currdat;
         end if;         

         result := BankDaysBetween(LastExpDat,currdat);
         
     end if;
     end if;
     
     
     return result;
  end; 
 
 
